(window.GIM_TS=window.GIM_TS||{})["Nedarim.3"]={"from":72,"a":[["\u0003\"זאת\"\u0004 שבפסוק המתחיל ב\u0003\"\u0004וזאת \u0003המצוה\"\u0004 (דברים ו, א), \u0003\"ידרך\"\u0004 של הפסוק שיש בו \u0003\"הדרך\"\u0004 (ירמיה נא, ג), והמלה \u0003\"חמש\"\u0004 שבפסוק שנאמר בו \u0003\"\u0004ו\u0003פאת נגב\"\u0004 (יחזקאל מח, טז), המלה \u0003\"אם\"\u0004 שבפסוק בו נאמר \u0003\"כי גאל\"\u0004 (רות ג, יב) — \u0003הלין כתבן ולא קריין\u0004 \u0005[אלה נכתבות ואינן נקראות].\u0006","\u0003אמר רב אחא בר אדא: במערבא פסקין להדין פסוקא לתלתא פסוקין\u0004 \u0005[בארץ ישראל פוסקים,\u0006 מחלקים, \u0005את הפסוק הזה לשלושה פסוקים]:\u0006 \u0003\"ויאמר ה' אל משה הנה אנכי בא אליך בעב הענן\u0004 בעבור ישמע העם בדברי עמך וגם בך יאמינו לעולם ויגד משה את דברי העם אל ה'\u0003\"\u0004 (שמות יט, ט).","\u0003אמר ר' חמא בר' חנינא: לא העשיר משה\u0004 רבינו \u0003אלא מפסולתן\u0004 (שארית הפיסול) \u0003של לוחות\u0004 הברית, \u0003שנאמר: \"פסל לך שני לחת אבנים כראשנים\"\u0004 (שמות לד, א). \"פסל לך\" כוונתו: \u0003פסולתן — שלך יהא.\u0004 וכיון שהלוחות היו של אבן יקרה מאד, היתה פסולתם אבנים טובות.","\u0003אמר ר' יוסי בר' חנינא: לא ניתנה תורה\u0004 מתחילה \u0003אלא למשה ולזרעו, שנאמר: \"כתב לך\"\u0004 (שמות לד, כז) וכן נאמר: \u0003\"פסל לך\"\u0004 (שמות יט, א), ולמדו חכמים: \u0003מה פסולתן שלך — אף כתבן שלך.\u0004 אלא \u0003משה נהג בה טובת עין ונתנה לישראל, ועליו הכתוב אומר: \"טוב עין הוא יברך\u0004 כי נתן מלחמו לדל\u0003\"\u0004 (משלי כב, ט).","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב חסדא:\u0004 הלא נאמר \u0003\"ואתי צוה ה' בעת ההיא ללמד אתכם\u0004 חוקים ומשפטים\u0003\"\u0004 (דברים ד, יד), משמע שמתחילה משה נצטווה ללמד תורה לישראל! ומשיבים: יש להבין \u0003ואותי צוה —\u0004 לעצמי, \u0003ואני\u0004 רציתי ולימדתי \u0003לכם.\u0004 ומקשים עוד: הרי נאמר \u0003\"ראה למדתי אתכם חקים ומשפטים כאשר צוני ה' אלהי\"\u0004 (דברים ד, ה)! ומתרצים: \u0003אותי צוה\u0004 עבור עצמי, \u0003ואני\u0004 עושה \u0003לכם\u0004 טובה ומלמדכם.","ומקשים: הרי נאמר \u0003\"ועתה כתבו לכם את השירה הזאת\u0004 ולמדה את בני ישראל\u0003\"\u0004 (דברים לא, יט), משמע שנצטווה משה ללמדה לישראל! ומשיבים: על \u0003השירה\u0004 של \"האזינו\" \u0003לחודה\u0004 \u0005[לבדה]\u0006 נצטווה ולא על שאר התורה. על כך מקשים: הרי נאמר \u0003\"למען תהיה לי השירה הזאת לעד בבני ישראל\"\u0004 (דברים לא, יט), ומשמע שאין הכוונה לשירה אלא לכל התורה שכתובות בה המצוות! \u0003אלא\u0004 יש לומר כי התורה כמו שהיא ניתנה באמת לכל ישראל, ומה שאמר ר' יוסי בר' חנינא שניתנה למשה הכוונה היא ל\u0003פילפולא בעלמא\u0004 \u0005[פילפול בלבד].\u0006 שיש דברים בפילפולה ובהעמקתה של תורה שהיו מתנה מיוחדת למשה רבינו, והוא נתנם בטובתו לישראל.","\u0003אמר ר' יוחנן: אין הקדוש ברוך הוא משרה שכינתו אלא על\u0004 מי שהוא \u0003גבור ועשיר וחכם ועניו, וכולן\u0004 אנו למדים \u0003ממשה.\u0004 ומפרטים: \u0003גבור — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויפרש את האהל על המשכן\"\u0004 (שמות מ, יט), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003משה רבינו\u0004 עצמו \u0003פרסו, וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"עשר אמות ארך הקרש\" וגו'\u0004 (שמות כו, טז), משמע שהיה משה גבוה וגיבור כל כך שיכול היה לפרוס בעצמו את הכיסוי מעל לקרשים. ומקשים: \u0003אימא דאריך וקטין\u0004 \u0005[אמור ש\u0006היה \u0005ארוך ורזה]\u0006 ואין ללמוד מכאן שהיה גיבור!","\u0003אלא מן הדין קרא\u0004 \u0005[הכתוב הזה]\u0006 למדים שהיה משה גיבור, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואתפש בשני הלחת ואשליכם מעל שתי ידי ואשברם\"\u0004 (דברים ט, יז), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003הלוחות\u0004 היה \u0003ארכן ששה\u0004 טפחים \u0003ורחבן ששה ועביין שלשה,\u0004 ואם משה היה יכול לשאת ולהשליך משא כבד כזה משמע שהיה גיבור.","שהיה \u0003עשיר —\u0004 שנאמר: \u0003\"פסל לך\"\u0004 (שמות לד, א), ולמדו מכאן: \u0003פסולתן\u0004 של לוחות הברית \u0003שלך יהא,\u0004 ופסולת זו היתה כולה אבנים טובות. שהיה משה רבינו \u0003חכם\u0004 למדים מדברי \u0003רב ושמואל, דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003חמשים שערי בינה נבראו בעולם, וכולם נתנו למשה חסר אחת, שנאמר: \"ותחסרהו מעט מאלהים\"\u0004 (תהלים ח, ו). \u0003עניו — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והאיש משה ענו מאד\"\u0004 (במדבר יב, ג).","\u0003אמר ר' יוחנן: כל הנביאים עשירים היו, מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה — \u0003ממשה ומשמואל מעמוס ומיונה\u0004 שהיו כולם עשירים.","\u0003משה\u0004 רבינו — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"לא חמור אחד מהם נשאתי\"\u0004 (במדבר טז, טו), ונברר, למה הכוונה בדברים אלה: \u0003אי\u0004 \u0005[אם]\u0006 כוונתו שלא לקח מהם \u0003בלא אגרא\u0004 \u0005[שכר],\u0006 שלא הפקיע חמור לעצמו, וכי כוונתו של משה בדבריו \u0003לאפוקי מאן דשקל\u0004 \u0005[להוציא מי שלוקח]\u0006 \u0003בלא\u0004 לשלם \u0003אגרא\u0004 \u0005[שכר]?\u0006 הרי אדם כזה הוא גזלן! \u0003אלא\u0004 ש\u0003אפילו באגרא\u0004 \u0005[בשכר]\u0006 לא לקח. ומכאן שהיה עשיר ולא נצרך אף לקנות דבר. ודוחים: מכאן אין ראיה, \u0003דילמא\u0004 \u0005[שמא]\u0006 להיפך \u0003משום\u0004 ש\u0003עני הוה\u0004 \u0005[היה]\u0006 ולא היה לו כסף לשלם עבור החמור. \u0003אלא\u0004 למדים זאת \u0003מן\u0004 הכתוב בענין לוחות הברית \u0003\"פסל לך\"\u0004 (שמות לד, א) — \u0003פסולתן יהא שלך.\u0004","ש\u0003שמואל\u0004 היה עשיר אנו למדים ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנני ענו בי נגד ה' ונגד משיחו את שור מי לקחתי וחמור מי לקחתי\"\u0004 (שמואל א יב, ג). \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא מתכוון לומר שלא לקח \u0003בחנם,\u0004 האם כוונתו בדבריו \u0003לאפוקי מאן דשקל\u0004 \u0005[להוציא מי שלוקח]\u0006 \u0003בחנם\u0004 שלא כדין?! \u0003אלא,\u0004 ש\u0003אפילו בשכר\u0004 לא לקח, מפני שהיה לו הכל משלו. ומקשים: \u0003דלמא\u0004 \u0005[שמא]\u0006 משום ש\u0003עני הוה\u0004 \u0005[היה]\u0006 ולכן לא יכול לקחת בשכר. \u0003אלא מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ותשבתו הרמתה כי שם ביתו\"\u0004 (שמואל א ז, יז), \u0003ואמר רבא: כל מקום שהלך — ביתו עמו.\u0004 ומכאן שהיה עשיר ויכול היה להרשות לעצמו לקחת את כל חפציו ממקום למקום.","\u0003אמר רבא: גדול מה שנאמר בשמואל יותר משנאמר במשה\u0004 רבינו, ש\u0003אילו במשה רבינו כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"לא חמור אחד מהם נשאתי\"\u0004 וכוונתו ש\u0003אפילו בשכר\u0004 לא לקח מהם בעל כרחם, \u0003ואילו גבי\u0004 \u0005[אצל]\u0006 \u0003שמואל אפילו ברצון,\u0004 שהאיש רצה ששמואל ישתמש בשלו, \u0003לא שכרו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמרו לא עשקתנו ולא רצותנו\u0004 ולא לקחת מיד איש מאומה\u0003\"\u0004 (שמואל א יב, ד), ואפילו ברצון (\"רצותנו\").","שהיה \u0003עמוס\u0004 עשיר, למדים ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויען עמוס ויאמר אל אמציה לא נביא אנכי ולא בן נביא אנכי כי בוקר אנכי ובולס שקמים\"\u0004 (עמוס ז, יד) ועניינו \u0003כדמתרגם\u0004 \u0005[כמו שמתרגם]\u0006 \u0003רב יוסף: ארי מרי גיתי אנא ושקמין לי בשפלתא\u0004 \u0005[כי בעל עדרים אני ושקמים\u0006 יש \u0005לי בשפלה]\u0006 \u0003וגו'.\u0004 מכאן למדים שהיה עשיר.","שהיה \u0003יונה\u0004 עשיר \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויתן שכרה וירד בה\"\u0004 (יונה א, ג) ו\u0003אמר ר' יוחנן: שנתן שכרה של\u0004 ה\u0003ספינה כולה. אמר ר' רומנוס: שכרה של ספינה הויא\u0004 \u0005[היה]\u0006 \u0003ארבע אלפים דינרי דהבא\u0004 \u0005[זהב].\u0006","\u0003ואמר ר' יוחנן: בתחלה היה משה\u0004 רבינו \u0003למד תורה ומשכחה, עד שניתנה לו במתנה, שנאמר: \"ויתן אל משה ככלתו לדבר אתו\"\u0004 (שמות לא, יח) ומכיון שניתנה לו במתנה נעשתה שלו, ויכול היה לזכור אותה.","\u0003ו\u0004המדיר את חבירו הנאה ממנו \u0003זן את אשתו ואת בניו\u0004 של המודר, \u0003אף על פי שהוא,\u0004 המודר עצמו, \u0003חייב במזונותן\u0004 ונהנה בכך שאחר זן אותם. \u0003ו\u0004אולם \u0003לא יזון את בהמתו\u0004 של המודר \u0003בין\u0004 שהיא בהמה \u0003טמאה בין\u0004 שהיא בהמה \u0003טהורה. ר' אליעזר אומר: זן את הטמאה ואינו זן את הטהורה. אמרו לו: מה\u0004 ההבדל \u0003בין טמאה לטהורה? אמר להו\u0004 \u0005[להם]:\u0006 \u0003שהטהורה\u0004 אף ש\u0003נפשה\u0004 (חייה הם) \u0003לשמים, ו\u0004אולם \u0003גופה שלו,\u0004 שהלא יכול לאכול אותה, ונמצא שנהנה במישרין מן המזון שמזינים אותה. \u0003ו\u0004אילו בהמה \u0003טמאה\u0004"],["\u0003נפשה וגופה לשמים,\u0004 שהרי אינו יכול לאכול את בשרה. \u0003אמרו לו: אף הטמאה נפשה לשמים וגופה שלו, שאם ירצה — הרי הוא מוכרה לגוים או מאכילה לכלבים.\u0004","\u0003אמר רב יצחק בר חנניה אמר רב הונא: המודר הנאה מחבירו — מותר להשיא לו בתו. הוי\u0004 \u0005[היה עוסק,\u0006 מתקשה\u0005]\u0006 \u0003בה ר' זירא: במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בשנכסי אבי\u0004 ה\u0003כלה אסורין על החתן, הרי\u0004 כשמשיא לו את בתו נמצא ש\u0003מוסר לו שפחה לשמשו\u0004 ומהנה אותו בכך!","\u0003אלא\u0004 יש לומר שמדובר \u0003ב\u0004מקרה ש\u0003נכסי\u0004 ה\u0003חתן אסורין על אבי\u0004 ה\u0003כלה,\u0004 ואין אבי הכלה נהנה מרכוש החתן למרות שהלה מפרנס את בתו. אולם אם כן, הלא \u0003גדולה מזו אמרו\u0004 במשנה: \u0003זן את אשתו ואת בניו ואף על פי שהוא חייב במזונותן,\u0004 ואין זה נחשב כנהנה ממנו, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 כחידוש ש\u0003מותר\u0004 המודר \u0003להשיא לו\u0004 למדיר את \u0003בתו?!\u0004 הלא דבר זה מובן מאליו!","אלא \u0003לעולם\u0004 יש לפרש שמדובר \u0003ב\u0004מקרה \u0003שנכסי אבי\u0004 ה\u0003כלה אסורין על החתן, ו\u0004מדובר פה \u0003בבתו בוגרת\u0004 שהאב אינו רשאי להשיאה בעצמו בעל כרחה, \u0003ו\u0004עושה זאת רק \u0003מדעתה,\u0004 ואם כן לא הוא מהנה אותו.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003המודר הנאה מחבירו — אסור להשיא לו בתו\u0004 הקטנה, \u0003אבל משיאו בתו בוגרת ומדעתה.\u0004","וכיוצא בזה \u0003אמר ר' יעקב: המדיר בנו\u0004 מהנאה כדי לאלץ את הבן שילך \u0003ל\u0004עסוק ב\u0003תלמוד תורה — מותר\u0004 בכל זאת להנות אותו בהנאה קטנה כגון: \u0003למלאות לו חבית של מים, ולהדליק לו את הנר. ר' יצחק אמר:\u0004 אף \u0003לצלות לו דג קטן. אמר ר' ירמיה אמר ר' יוחנן: המודר הנאה מחבירו מותר להשקותו כוס של שלום.\u0004 ושואלים: \u0003מאי ניהו\u0004 \u0005[מה הוא]\u0006 כוס של שלום זה? \u0003הכא תרגימו\u0004 \u0005[כאן,\u0006 בבבל, \u0005היו מתרגמים\u0006 ומסבירים\u0005]:\u0006 \u0003כוס של בית האבל,\u0004 כוס יין שנותנים לאבלים לשתות בסעודת הבראה. \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל היו אומרים]\u0006 ומפרשים שהכוונה היא: \u0003כוס של בית המרחץ,\u0004 ששותים כשיוצאים מבית המרחץ.","שנינו במשנה: \u0003ולא יזון את בהמתו בין\u0004 טמאה בין טהורה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003יהושע איש עוזא אומר:\u0004 המודר הנאה מחבירו \u0003זן\u0004 את \u0003עבדיו ושפחותיו הכנענים, ולא יזון את בהמתו בין טמאה בין טהורה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל? ומסבירים: \u0003עבדיו ושפחותיו הכנענים — למנחרותא עבידן\u0004 \u0005[לעבודה\u0006 הם \u0005עשויים],\u0006 \u0003בהמה — לפטומא עבידא\u0004 \u0005[לפיטום\u0006 היא \u0005עשויה,\u0006 מיועדת\u0005]\u0006 ונמצא שנהנה מבשרה, אם באכילתה (של הבהמה הטהורה), אם במכירתה (של הטמאה) לגוי.","\u0003המודר הנאה מחבירו ונכנס לבקרו\u0004 ביקור חולים — \u0003עומד\u0004 בביתו של המודר \u0003אבל לא יושב\u0004 שם. \u0003ומרפאו רפואת נפש, אבל לא רפואת ממון.\u0004"],["\u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים\u0006 כאן\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשנכסי\u0004 ה\u0003מבקר אסורין על\u0004 ה\u0003חולה — אפילו יושב נמי\u0004 \u0005[גם כן]\u0006 מותר, ומדוע לא ישב המבקר? והרי לו מותר ליהנות משל החולה! \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשנכסי\u0004 ה\u0003חולה אסורין על המבקר — אפילו עומד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 שהרי הוא נהנה מעצם הכניסה לבית! \u0003אמר שמואל: לעולם\u0004 תפרש כי מדובר \u0003בשנכסי\u0004 ה\u0003מבקר אסורין על החולה, ובמקום שנוטלין שכר על הישיבה\u0004 עם החולה, והמבקר חוסך מן החולה את הצורך לשכור מי שישב עימו, ומשום כך אסור לשבת אצלו, \u0003ואין נוטלין שכר על העמידה.\u0004","ושואלים: \u0003מאי פסקא\u0004 \u0005[מה הפסק,\u0006 החילוק\u0005]\u0006 שאתה מחלק את הדברים דווקא בדרך זו? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 ש\u0003אף במקום שנוטלין שכר\u0004 לשבת עם החולה, \u0003על הישיבה — בעי למשקל\u0004 \u0005[צריך,\u0006 ניתן, \u0005לקחת],\u0006 \u0003על העמידה — לא בעי למשקל\u0004 \u0005[צריך לקחת].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 והסבר \u0003כ\u0004פי שאמר לענין אחר \u0003ר' שמעון בן אליקים,\u0004 שאסרו על מודר הנאה להיכנס בשדה שבעליו הדירו הנאה ממנו, \u0003גזירה שמא ישהא בעמידה\u0004 יותר מכפי המותר לו. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003גזירה שמא ישהא בישיבה\u0004 יותר ממה שנצרך למצוה.","\u0003עולא אמר: לעולם\u0004 תפרש את משנתנו \u0003ב\u0004מקרה \u0003שנכסי\u0004 ה\u0003חולה אסורין על המבקר, וכגון\u0004 ש\u0003לא אדריה\u0004 \u0005[הדיר אותו]\u0006 החולה \u0003מן\u0004 דבר שהוא צורך \u0003חיותיה\u0004 \u0005[חייו]\u0006 של החולה ממש. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו יושב נמי\u0004 \u0005[גם כן]\u0006 יהא מותר, שהרי אמרנו שלא הדיר אותו בדבר הנוגע לחייו! ומשיבים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אפשר\u0004 לעשות את כל הדרוש \u0003בעמידה,\u0004 ואסור לו ליהנות יותר מן ההכרח.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: המודר הנאה מחבירו ו\u0003חלה הוא,\u0004 המדיר — \u0003נכנס\u0004 המודר \u0003לבקרו,\u0004 אם \u0003חלה בנו — שואלו בשוק\u0004 על שלום הבן, אבל לא נכנס לבקרו. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דברי \u0003עולא,\u0004 ש\u0003אמר\u0004 והעמיד את המשנה \u0003ב\u0004מקרה \u0003שנכסי\u0004 ה\u0003חולה אסורין על המבקר, וכגון\u0004 ש\u0003לא אדריה מן חיותיה\u0004 \u0005[הדיר אותו מחייו]\u0006 — \u0003שפיר\u0004 \u0005[יפה,\u0006 טוב\u0005]\u0006 ומובן שאין תנאי זה שייך כשבנו חולה, ואם כן אסור המודר להיכנס לביתו.","\u0003אלא ל\u0004דעת \u0003שמואל\u0004 ש\u0003אמר\u0004 והעמיד את המשנה \u0003ב\u0004מקרה \u0003שנכסי\u0004 ה\u0003מבקר אסורין על החולה, מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003הוא ומאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003בנו\u0004 ומדוע אסור לו לבקר את הבן? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה שמואל \u0005לומר]\u0006 \u0003לך: מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003ב\u0004מקרה \u0003שנכסי\u0004 ה\u0003מבקר אסורין על החולה,\u0004 ואילו ה\u0003ברייתא\u0004 מדברת \u0003ב\u0004מקרה \u0003שנכסי\u0004 ה\u0003חולה אסורין על המבקר.\u0004","ושואלים: \u0003מאי פסקא\u0004 \u0005[מה הפסק,\u0006 החלוקה\u0005],\u0006 מדוע אתה מסביר את הדברים דווקא כך? \u0003אמר רבא (אמר): שמואל\u0004"],["\u0003מתניתין קשיתיה\u0004 \u0005[משנתנו היתה קשה לו];\u0006 \u0003מאי איריא דתני\u0004 \u0005[מה שייך,\u0006 מדוע דווקא \u0005ששנה]\u0006 \u0003עומד אבל לא יושב? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמדובר במקרה ש\u0003נכסי\u0004 ה\u0003מבקר אסורין על החולה.\u0004","כיון שהמשנה עוסקת בפרטי דין ביקור חולים, מביאים דברים שנאמרו בענין זה. \u0003אמר ריש לקיש: רמז לביקור חולין מן התורה מנין — שנאמר\u0004 בעדת קורח: \u0003\"אם כמות כל האדם ימתון אלה ופקדת כל האדם\u0004 יפקד עליהם לא ה' שלחני\u0003\"\u0004 (במדבר טז, כט). ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד לומדים ביקור חולים מפסוק זה? \u0003אמר רבא,\u0004 כך אמר משה: \u0003אם כמות כל האדם ימותון אלה,\u0004 עדת קורח, כמיתת שאר בני אדם \u0003שהן חולים\u0004 קודם מותם \u0003ומוטלים בעריסתן\u0004 (במיטתם), \u0003ובני אדם מבקרים אותן\u0004 (\"ופקודת כל האדם\" — שבני אדם פוקדים=מבקרים אותם), ואם כך יארע להם \u0003מה הבריות אומרים — לא ה' שלחני לזה.\u0004","כיון שהזכרנו ענין עדת קורח מביאים מה ש\u0003דרש רבא: \"\u0004ו\u0003אם בריאה יברא ה'\"\u0004 (במדבר טז, ל), שמפרש את כפל הלשון \"בריאה יברא\": \u0003אם בריאה\u0004 (ברואה) כבר \u0003גיהנם — מוטב תהיה, אם לאו — יברא ה'\u0004 בריאה זו מחדש.","שואלים: \u0003איני\u0004 \u0005[כך הוא]?\u0006 וכי יש ספק בדבר אם נברא כבר הגיהנם? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שבעה דברים נבראו קודם שנברא העולם, אלו הן: תורה, ותשובה, גן עדן, וגיהנם, כסא הכבוד, ובית המקדש, ושמו של משיח.\u0004","וראיות לכל דבר: \u0003תורה — דכתיב\u0004 \u0005[שנאמר]\u0006 בפרק המדבר על התורה: \u0003\"ה' קנני ראשית דרכו\u0004 קדם מפעליו מאז\u0003\"\u0004 (משלי ח, כב).","\u0003תשובה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בטרם הרים ילדו ותחולל\u0004 ארץ ותבל... \u0003תשב אנוש עד דכא\u0004 ותאמר שובו בני אדם\u0003\"\u0004 (תהלים צ, ב-ג).","\u0003גן עדן — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויטע ה' אלהים גן בעדן מקדם\" וגו'\u0004 (בראשית ב, ח) שמפרשים אותו \"מקדם\" — קודם שנברא העולם.","\u0003גיהנם — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי ערוך מאתמול תפתה\"\u0004 (ישעיה ל, לג), כלומר, מלפני היום של העולם (\"מאתמול\"), מוכן כבר (\"ערוך\") הגיהנם (\"תפתה\").","\u0003כסא כבוד — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נכון כסאך מאז\u0004 מעולם אתה\u0003\"\u0004 (תהלים צג, ב).","\u0003בית המקדש — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כסא כבוד מרום מראשון\u0004 מקום מקדשנו\u0003\"\u0004 (ירמיה יז, יב), ו\"מראשון\" משמעו — מתחילה.","\u0003שמו של משיח — דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"יהי שמו לעולם\u0004 לפני שמש ינון שמו\" (תהלים עב, יז). כלומר, שעוד לפני שנברא השמש כבר היה שמו של המשיח.","ואם כן לא ניתן לפרש את הפסוק כדברי רבא, שהיה למשה ספק אם נברא כבר הגיהנם, \u0003אלא\u0004 כך יש לפרש את כפל הלשון \"בריאה יברא\" — \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 משה: \u0003אי איברי ליה פומא\u0004 \u0005[אם נברא לו,\u0006 לגיהנם, \u0005פה] —\u0006 \u0003מוטב, ואם לא — יברא ה'.\u0004 ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"\u0004ו\u0003אין כל חדש תחת השמש\"\u0004 (קהלת א, ט), שאין דברים חדשים לגמרי נבראים בעולם! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אי הכא\u0004 \u0005[אם כאן]\u0006 \u0003לא מקרב פומא\u0004 \u0005[קרוב הפה]\u0006 של הגיהנם — \u0003להכא ליקרב\u0004 \u0005[לכאן יקרב]\u0006 ודבר זה אינו בכלל בריאה חדשה.","כיון שהזכירו את מחלוקת קרח עם משה, מביאים עוד מה ש\u0003דרש רבא ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים אותה]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"שמש ירח עמד זבלה\u0004 לאור חיציך יהלכו לנוגה ברק חניתך\u0003\"\u0004 (חבקוק ג, יא), \u0003שמש וירח ב\u0004רקיע הנקרא \u0003\"זבול\" מאי בעיין\u0004 \u0005[מה\u0006 הם \u0005מבקשים\u0006 שם\u0005]?\u0006 שהרי אין שם מקום השמש והירח, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ברקיע\u0004 עצמו \u0003קביעי\u0004 \u0005[קבועים\u0006 הם\u0005]!\u0006 אלא, \u0003מלמד שעלו שמש וירח מרקיע לזבול, ואמרו לפניו: רבונו של עולם, אם אתה עושה דין לבן עמרם\u0004 כפי שביקש במחלוקתו עם קרח — \u0003אנו מאירים, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003אין אנו מאירין.\u0004","\u0003באותה שעה ירה בהן\u0004 הקדוש ברוך הוא \u0003חיצים וחניתות, אמר להם: בכל יום ויום\u0004 בני אדם עובדי עבודה זרה \u0003משתחוים לכם ואתם מאירים\u0004 ואינכם מוחים. \u0003בכבודי לא מחיתם, בכבוד בשר ודם מחיתם! ו\u0004משום כך מאז \u0003בכל יום ויום יורין בהן חיצין וחניתות,\u0004 ורק אז הם יוצאים \u0003ומאירים, שנאמר: \"לאור חציך יהלכו\u0004 לנוגה ברק חניתך\u0003\"\u0004 (חבקוק ג, יא).","ושוב לענין העיקרי של ביקור חולים, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 מצות \u0003ביקור חולים אין לה שיעור.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין לה שיעור\"? סבר רב יוסף למימר\u0004 \u0005[לומר]\u0006 כי הכוונה היא ש\u0003אין שיעור למתן שכרה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וכל\u0004 ה\u0003מצות\u0004 האחרות \u0003מי\u0004 \u0005[האם]\u0006 \u0003יש שיעור\u0004 ידוע \u0003למתן שכרן? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הוי זהיר במצוה קלה כבחמורה, שאין אתה יודע\u0004 כמה הוא \u0003מתן שכרן של מצות! אלא אמר אביי:\u0004 שאין לה שיעור ביחס שבין החולה והמבקר אותו, ש\u0003אפילו גדול\u0004 מבקר \u0003אצל קטן,\u0004 ואין ראוי שיאמר הגדול שאין הדבר לפי כבודו. \u0003רבא אמר:\u0004 אין לה שיעור בריבוי הפעמים בהן מבקר את החולה, ו\u0003אפילו מאה פעמים ביום.\u0004","\u0003אמר ר' אחא בר חנינא: כל המבקר חולה נוטל\u0004 חלק \u0003אחד מששים בצערו. אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אם כן ליעלון שיתין ולוקמוה\u0004 \u0005[שיכנסו שישים\u0006 אנשים לבקרו \u0005ויעמידוהו\u0006 מחוליו\u0005]\u0006 על ידי כך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כעישורייתא דבי\u0004 \u0005[כמו העישורים של בית\u0006 מדרשו\u0005]\u0006 של \u0003רבי,\u0004 שאמר שנותן לכל אחת מבנותיו עשירית מרכושו, והכוונה היא עשירית ממה שנשאר לאחר שנטלו הקודמות לה. ואף כאן, כל מבקר חולה נוטל אחד משישים ממה שנשאר לפני שבא, ולכן לעולם נשאר מקצת חוליו של החולה. \u0003ו\u0004עוד, שנטילת חלק מהחולי על ידי המבקר את החולה היא דווקא במקרה שהחולה הוא \u0003בן גילו\u0004 (מזלו) של המבקר, ולא בכל אדם.","ומסבירים מהו אותו ענין עשיריות של רבי, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003רבי אומר: בת הניזונית מנכסי אחין\u0004 לאחר מות האב — \u0003נוטלת עישור נכסים\u0004 לנדוניה. \u0003אמרו לו לרבי: לדבריך מי שיש לו עשר בנות ובן,\u0004 נמצא ש\u0003אין לו לבן במקום בנות כלום,\u0004 שהן נוטלות את כל הירושה! \u0003אמר להן: ראשונה נוטלת עישור נכסים, שניה\u0004 נוטלת עישור \u0003במה ששיירה\u0004 ראשונה, \u0003שלישית במה ששיירה\u0004 שניה, \u0003וחוזרות וחולקות בשוה.\u0004 שלפי מספר הבנות הן חוזרות ומחלקות את הכסף המגיע להן בשווה, ובאופן זה תמיד נשאר משהו לבן.","מסופר: \u0003רב חלבו חלש\u0004 \u0005[חלה],\u0006 \u0003נפק אכריז\u0004 \u0005[יצא\u0006 ו\u0005הכריז]\u0006 \u0003רב כהנא:\u0004"],["\u0003רב חלבו באיש\u0004 \u0005[חלה].\u0006 \u0003לא איכא\u0004 \u0005[היה]\u0006 מי \u0003דקא אתי\u0004 \u0005[שבא]\u0006 לבקרו. \u0003אמר להו\u0004 \u0005[להם]\u0006 רב כהנא לחכמים: \u0003לא כך היה מעשה בתלמיד אחד מתלמידי ר' עקיבא שחלה. לא נכנסו חכמים לבקרו, ונכנס ר' עקיבא\u0004 עצמו \u0003לבקרו,\u0004 וציווה לתלמידיו לטפל בו, \u0003ובשביל שכיבדו\u0004 (טאטאו וניקו) \u0003וריבצו\u0004 (מים על הרצפה) \u0003לפניו, חיה\u0004 (הבריא). \u0003אמר לו\u0004 התלמיד: \u0003רבי, החייתני. יצא ר' עקיבא ודרש: כל מי שאין מבקר חולים\u0004 הריהו \u0003כאילו שופך דמים,\u0004 שייתכן שהחולה נמצא בלי מי שמטפל בו, ואם אין מי שמבקר אותו, אין יודעים מה מצבו ועלול לחלות יותר.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: כל המבקר את החולה גורם לו שיחיה, וכל שאינו מבקר את החולה גורם לו שימות.\u0004 ושואלים: \u0003מאי גרמא\u0004 \u0005[במה\u0006 הוא \u0005גורם]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003כל המבקר את החולה מבקש עליו רחמים שיחיה, וכל שאין מבקר את החולה מבקש עליו רחמים שימות — שימות סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 מדוע מבקש עליו שימות? \u0003אלא: כל שאין מבקר חולה אין מבקש עליו רחמים, לא שיחיה ולא שימות,\u0004 ומשום שיכול היה להצילו בתפילתו, הרי זה כגורם לו שימות.","מסופר: \u0003רבא, יומא קדמאה דחליש\u0004 \u0005[ביום הראשון שהיה מרגיש חולשה]\u0006 \u0003אמר להון\u0004 \u0005[היה אומר להם,\u0006 לבני ביתו\u0005]:\u0006 \u0003לא תיגלו לאיניש\u0004 \u0005[אל תגלו לאיש]\u0006 שאני חולה, כדי ש\u0003לא לתרע מזליה\u0004 \u0005[יורע מזלי].\u0006 \u0003מכאן ואילך,\u0004 כשהורע מצבו, \u0003אמר להון\u0004 \u0005[\u0006היה \u0005אומר להם]:\u0006 \u0003פוקו ואכריזו בשוקא\u0004 \u0005[צאו והכריזו בשוק]\u0006 שאני חולה. \u0003דכל דסני לי ליחדי לי\u0004 \u0005[שכל השונא אותי ישמח בי,\u0006 במחלתי\u0005],\u0006 \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"בנפל אויבך אל תשמח\"\u0004 (משלי כד, יז), ונאמר אחריו: \"פן יראה ה' ורע בעיניו והשיב מעליו אפו\" (משלי כד, יח), \u0003ודרחים לי ליבעי עלי רחמי\u0004 \u0005[ו\u0006מי \u0005שאוהב אותי יבקש עלי רחמים].\u0006","\u0003אמר רב: כל המבקר את החולה ניצול מדינה של גיהנם, שנאמר: \"אשרי משכיל אל דל ביום רעה ימלטהו ה'\"\u0004 (תהלים מא, ב), ומסביר את הדברים: \u0003אין דל אלא חולה, שנאמר\u0004 בתפילת חזקיה בחוליו: \u0003\"מדלה יבצעני\"\u0004 (ישעיה לח, יב), \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003מן הדין קרא\u0004 \u0005[מהפסוק הזה]\u0006 אפשר ללמוד, ששאלו את אמנון בן דוד בחוליו: \u0003\"מדוע אתה ככה דל בן המלך בבקר בבקר\" וגו'\u0004 (שמואל ב יג, ד). ו\u0003אין רעה אלא גיהנם, שנאמר: \"כל פעל ה' למענהו וגם רשע ליום רעה\"\u0004 (משלי טז, ד), שעונשו האחרון של הרשע הוא בגיהנם.","\u0003ואם ביקר מה שכרו?\u0004 ותוהים: \u0003מה שכרו?!\u0004 הלא \u0003כדאמר\u0004 \u0005[כפי שאמר]:\u0006 \u0003ניצול מדינה של גיהנם! אלא\u0004 השאלה היתה: \u0003מה שכרו בעולם הזה,\u0004 והתשובה לכך בהמשך הכתוב:","\u0003\"ה' ישמרהו ויחיהו ואשר בארץ ואל תתנהו בנפש איביו\"\u0004 (תהלים מא, ג) והוא מפרשו: \u0003\"ה' ישמרהו\" — מיצר הרע, \"ויחיהו\" —\u0004 שיצילהו \u0003מן היסורין, \"ואשר בארץ\" — שיהו הכל מתכבדין בו, \"ואל תתנהו בנפש איביו\" —\u0004 כוונתו \u0003שיזדמנו לו ריעים כ\u0004דרך שנזדמנו ל\u0003נעמן,\u0004 שהיו לו ידידים שיעצו לו לפנות לאלישע וגרמו בכך \u0003שריפו\u0004 (ריפאו) \u0003את צרעתו. ואל יזדמנו לו ריעים כרחבעם ש\u0004על ידי עצתם \u0003חילקו את מלכותו.\u0004","ובאותו ענין \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: אם יאמרו לך ילדים \"בנה\" וזקנים\u0004 יאמרו \u0003\"סתור\" — שמע לזקנים ואל תשמע לילדים, שבנין ילדים\u0004 אינו אלא \u0003סתירה, וסתירת זקנים\u0004 הינה \u0003בנין. וסימן לדבר: רחבעם בן שלמה\u0004 (ראה מלכים א יב, כא). שאילו היה שומע בעצת הזקנים ונכנע לפי שעה, לא היתה מלכותו נחלקת.","\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: לא ליסעוד איניש קצירא\u0004 \u0005[יבקר אדם\u0006 את \u0005החולה]\u0006 \u0003לא בתלת שעי קדמייתא\u0004 \u0005[בשלוש שעות ראשונות]\u0006 של היום, \u0003ולא בתלת שעי בתרייתא דיומא\u0004 \u0005[בשלוש שעות אחרונות של היום],\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליסח דעתיה\u0004 \u0005[יסיח דעתו]\u0006 \u0003מן רחמי\u0004 \u0005[הרחמים].\u0006 ומסביר: \u0003תלת שעי קדמייתא\u0004 \u0005[שלוש שעות ראשונות]\u0006 — \u0003רווחא דעתיה\u0004 \u0005[מרווחת דעתו],\u0006 שלאחר מנוחת הלילה מחלתו נחלשת קצת והמבקר סבור שאין צורך להתפלל עליו. \u0003בתרייתא\u0004 \u0005[\u0006בשעות \u0005האחרונות\u0006 של היום\u0005] —\u0006 \u0003תקיף חולשיה\u0004 \u0005[מתגברת חולשתו]\u0006 וסבור המבקר שהוא כבר לאחר יאוש ואין טעם להתפלל עליו.","\u0003אמר רבין אמר רב: מניין שהקדוש ברוך הוא\u0004 עצמו \u0003זן את החולה — שנאמר: \"ה' יסעדנו על ערש דוי\" וגו'\u0004 (תהלים מא, ד), ומפרש כאן \"יסעדנו\" — יתן לו סעודה, יזון אותו. \u0003ו\u0004עוד \u0003אמר רבין אמר רב\u0004 בענין זה: \u0003מניין שהשכינה שרויה למעלה ממטתו של החולה — שנאמר: \"ה' יסעדנו על ערש דוי\",\u0004 שמפרש שה' על ערשו ממש.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הנכנס לבקר את החולה לא ישב לא על גבי מטה ולא על גבי ספסל ולא על גבי כסא\u0004 שהם למעלה מן החולה, \u0003אלא מתעטף\u0004 בבגדו, בדרך כבוד, \u0003ויושב על גבי קרקע, מפני שהשכינה שרויה למעלה ממטתו של חולה, שנאמר: \"ה' יסעדנו על ערש דוי\",\u0004 ואין ראוי שאדם ישב למעלה ממקום השכינה.","\u0003ו\u0004אגב מאמרים אלה של רבין בשם רב בענין ביקור חולים מביאים עוד ממה ש\u0003אמר רבין אמר רב:\u0004 כשיורד \u0003מטרא במערבא\u0004 \u0005[גשם בארץ ישראל] —\u0006 \u0003סהדא רבה\u0004 \u0005[עד גדול]\u0006 לכך הוא נהר \u0003פרת,\u0004 שבסופו של דבר מי גשמים אלה מגיעים לנהר פרת ומתרבים מימיו. \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003שמואל.\u0004 ש\u0003אמר שמואל: נהרא מכיפיה מתבריך\u0004 \u0005[הנהר מגדותיו מתברך]\u0006 ומשם באים המים, ולא מן הגשמים שבמקום רחוק. ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 אימרה זו של \u0003שמואל\u0004 על דברי \u0003שמואל\u0004 עצמו בענין אחר, ש\u0003אמר שמואל: אין המים מטהרין בזוחלין,\u0004 כלומר, אינם מטהרים כמי מעיין, שמי מעיין מטהרים כדינם אף כאשר הם זוחלים = נעים,"],["\u0003אלא פרת ביומי\u0004 \u0005[בימי]\u0006 \u0003תשרי בלבד\u0004 שאז אין בנהר מים אלא אותם שנובעים ממעיינותיו, אבל בשאר ימות השנה מעורבים בהם מי גשמים ושלגים.","ומסופר לפי סברה זו: \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל עבד להון\u0004 \u0005[היה עושה להן]\u0006 \u0003מקוואות לבנתיה\u0004 \u0005[לבנותיו]\u0006 כדי שיטבלו בהם \u0003ביומי\u0004 \u0005[בימי]\u0006 \u0003ניסן,\u0004 משום שסבר שמי הנהר מעורבים בזמן זה במי גשמים המרובים מהם בכמותם, ואינם יכולים לטהר בזוחלים, ולכן עשה להן מקוואות במקום אחר. \u0003ומפצי\u0004 \u0005[ומחצלות]\u0006 הניח להן מתחת רגליהן \u0003ביומי\u0004 \u0005[בימי]\u0006 \u0003תשרי\u0004 כשהיו טובלות בנהר עצמו, שלא יגרום הטיט שבקרקע הנהר לידי חציצה בטבילה.","\u0003אמר ר' אמי אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ואתה בן אדם עשה לך כלי גולה\"\u0004 (יחזקאל יב, ג) — \u0003זו נר וקערה\u0004"],["\u0003ושטיח,\u0004 שהגולה זקוק להם ויכול לקחתם איתו ממקום למקום. ובענין דומה, פירשו את הפסוק המדבר על הגלות \u0003\"\u0004ועבדת את אויביך... ו\u0003בחסר כל\"\u0004 (דברים כח, מח), \u0003אמר ר' אמי אמר רב:\u0004 משמעות \"בחוסר כל\" היא — \u0003בלא נר\u0004 לאור \u0003ובלא שלחן\u0004 לאכול עליו. \u0003רב חסדא אמר: בלא אשה. רב ששת אמר: בלא שמש\u0004 לסייע לו. \u0003רב נחמן אמר: בלא דעה. תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \"בחוסר כל\" פירושו \u0003בלא מלח ובלא רבב\u0004 (שומן) לטבל בהם את פיתו.","\u0003אמר אביי: נקטינן\u0004 \u0005[מוחזקים אנו] —\u0006 \u0003אין עני אלא בדעה.\u0004 כלומר, עוני אמיתי הוא עניות הדעת, וכדברי רב נחמן, שהרי זה חוסר כל. \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל היו אומרים]:\u0006 מי \u0003דדא ביה\u0004 \u0005[שזו,\u0006 הדעת, \u0005בו] —\u0006 \u0003כולא ביה\u0004 \u0005[הכל בו],\u0006 \u0003דלא דא ביה\u0004 \u0005[שאין זו בו] —\u0006 \u0003מה\u0004 יש \u0003ביה\u0004 \u0005[בו].\u0006 מי שאת \u0003דא קני\u0004 \u0005[זו קנה] —\u0006 \u0003מה\u0004 עוד \u0003חסר\u0004 לו, מי שאת \u0003דא\u0004 \u0005[זה]\u0006 \u0003לא קני\u0004 \u0005[קנה] —\u0006 \u0003מה קני\u0004 \u0005[קנה].\u0006","\u0003אמר ר' אלכסנדרי אמר ר' חייא בר אבא: אין החולה עומד מחליו\u0004 (מחלים) \u0003עד שמוחלין לו על כל עונותיו, שנאמר: \"הסלח לכל עונכי הרפא לכל תחלואיכי\"\u0004 (תהלים קג, ג). שקודם נאמר בפסוק \"הסולח לכל עונכי\" ורק אחר כך \"הרופא לכל תחלואיכי\". \u0003רב המנונא אמר:\u0004 כשמבריא הוא אף \u0003חוזר לימי עלומיו, שנאמר: \"רטפש בשרו מנער ישוב לימי עלומיו\"\u0004 (איוב לג, כה). על הפסוק \u0003\"כל משכבו הפכת בחליו\"\u0004 (תהלים מא, ד) \u0003אמר רב יוסף: לומר\u0004 ש\u0003משכח\u0004 החולה \u0003תלמודו\u0004 בזמן מחלתו, שכל מה שהיה מסודר אצלו — נהפך.","ומסופר, שאכן \u0003רב יוסף\u0004 עצמו \u0003חלש\u0004 \u0005[חלה],\u0006 \u0003איעקר ליה תלמודיה\u0004 \u0005[נעקר,\u0006 נשכח, \u0005ממנו תלמודו],\u0006 \u0003אהדריה\u0004 \u0005[החזיר אותו]\u0006 \u0003אביי קמיה\u0004 \u0005[לפניו],\u0006 שהזכיר לו מה ששכח. \u0003היינו דבכל דוכתא אמרינן\u0004 \u0005[\u0006ו\u0005זהו שבכל מקום אנו אומרים],\u0006 \u0003אמר רב יוסף: לא שמיע לי הדא שמעתא\u0004 \u0005[שמעתי\u0006 את \u0005השמועה הזו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: את אמריתה ניהלן, ומהא מתניתא אמריתה ניהלן\u0004 \u0005[אתה אמרת אותה לנו, ומברייתא זו אמרת לנו].\u0006 כי רב יוסף שכח, ואביי תלמידו היה מזכיר לו.","מסופר: \u0003כי הוה גמיר\u0004 \u0005[כאשר היה לומד]\u0006 \u0003רבי תלת עשרי אפי הילכתא\u0004 \u0005[שלוש עשרה פנים בהלכה]\u0006 בכל ענין, \u0003אגמריה\u0004 \u0005[לימדו]\u0006 את \u0003ר' חייא שבעה\u0004 פנים \u0003מנהון\u0004 \u0005[מהם].\u0006 \u0003לסוף חלש\u0004 \u0005[חלה]\u0006 \u0003רבי\u0004 ושכח כולם, \u0003אהדר\u0004 \u0005[חזר]\u0006 \u0003ר' חייא קמיה הנהו\u0004 \u0005[לפניו\u0006 על \u0005אותן]\u0006 \u0003שבעה אפי דאגמריה\u0004 \u0005[פנים שלימד אותו]\u0006 אבל \u0003שיתא אזדו\u0004 \u0005[שש הלכו,\u0006 נשכחו\u0005],\u0006 שהרי לא לימד אותן רבי לאחרים. \u0003הוה ההוא קצרא, הוה שמיע ליה\u0004 \u0005[היה כובס אחד\u0006 ש\u0005היה שומע אותו]\u0006 את \u0003רבי כדהוה גריס להו\u0004 \u0005[כשהיה לומד אותן],\u0006 את כל ההלכות הללו. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' חייא וגמר יתהון קמי קצרא\u0004 \u0005[ולמד אותן לפני,\u0006 אצל \u0005הכובס]\u0006 \u0003ואתא ואהדר יתהון קמי\u0004 \u0005[ובא והחזיר אותן לפני]\u0006 \u0003רבי. כד הוה חזי ליה\u0004 \u0005[כאשר היה רואה אותו]\u0006 \u0003רבי לההוא קצרא\u0004 \u0005[את הכובס ההוא]\u0006 \u0003אמר ליה\u0004 \u0005[\u0006היה \u0005אומר לו]\u0006 \u0003רבי: אתה עשית אותי ואת חייא,\u0004 שהרי ממך חזרנו ולמדנו דברים אלה ששכחנום. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003הכי קאמר ליה\u0004 \u0005[יש שאומרים\u0006 ש\u0005כך היה אומר לו]:\u0006 \u0003אתה עשית את חייא, וחייא עשה אותי.\u0004","\u0003ואמר ר' אלכסנדרי אמר ר' חייא בר אבא: גדול נס שנעשה לחולה יותר מן הנס שנעשה לחנניה מישאל ועזריה\u0004 שניצלו מכבשן האש. שבנס \u0003של חנניה מישאל ועזריה\u0004 הם ניצלו מ\u0003אש של הדיוט, ו\u0004אש זו \u0003הכל יכולים לכבותה. וזו של חולה\u0004 שאוחזת בו הקדחת, החום — אש \u0003של שמים היא, ומי יכול לכבותה?\u0004","\u0003ואמר ר' אלכסנדרי אמר ר' חייא בר אבא, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יהושע בן לוי: כיון שהגיע קיצו,\u0004 סוף ימיו הקצוב \u0003של אדם — הכל מושלים בו, שנאמר: \"והיה כל מצאי יהרגני\"\u0004 (בראשית ד, יד). שחשש קין שכיון שנגזרה עליו מיתה לאחר שהרג את הבל — שוב לא יוכל לעמוד בפני כל צרה, והכל יהרגוהו. \u0003רב אמר: מן הדין קרא\u0004 \u0005[מפסוק זה]\u0006 נלמד הדבר: \u0003\"למשפטיך עמדו היום כי הכל עבדיך\"\u0004 (תהלים קיט, צא). שכאשר נגזר משפטו של אדם למות — הכל נעשים עבדיו של הקדוש ברוך הוא להיות שליחים להמיתו.","ומסופר באותו ענין: \u0003רבה בר שילא אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003שכיב גברא\u0004 \u0005[מת אדם].\u0006 \u0003גבוה הוה\u0004 \u0005[היה],\u0006 \u0003רכיב גירדונא זוטרא\u0004 \u0005[רכוב\u0006 על \u0005פרד קטן],\u0006 \u0003מטא תיתורא\u0004 \u0005[הגיע לגשר]\u0006 \u0003איסתויט\u0004 \u0005[נבהל]\u0006 הפרד, \u0003שדייה וקא שכיב\u0004 \u0005[השליכו\u0006 לרוכב \u0005ומת].\u0006 שאף שהיה הוא גבוה והפרד קטן ולא היתה זו נפילה גדולה — מכל מקום מת בה. \u0003קרי על נפשיה\u0004 \u0005[קרא על עצמו]:\u0006 \u0003\"למשפטיך עמדו היום\".\u0004","\u0003שמואל חזייה לההוא קרוקיתא דעקרבא יתיבא על אקרוקתא ועברה נהראף טרקא גברא ומיית\u0004 \u0005[ראה עקרב אחד יושב על צפרדע ועובר\u0006 את \u0005הנהר, עקץ אדם\u0006 בצד השני של הנהר \u0005ומת]\u0006 אותו אדם. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003\"למשפטיך עמדו היום\u0004 כי הכל עבדיך\" שאפילו שרצים אלה הם עבדיו ושליחיו של הקדוש ברוך הוא, וכדי שייעקץ אותו אדם על ידי העקרב, שאינו יכול לעבור את המים, נזדמנה לעקרב צפרדע זו להעבירו.","\u0003אמר שמואל: אין מבקרין את החולה אלא למי שחלצתו חמה,\u0004 כלומר, מי שיש לו חום. ושואלים: \u0003לאפוקי מאי\u0004 \u0005[להוציא\u0006 את \u0005מה]?\u0006 שמדבריו נלמד שיש חולים אחרים שאין מבקרים אותם. ומשיבים: \u0003לאפוקי הא דתניא\u0004 \u0005[להוציא זו ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בן פרטא אומר משום\u0004 (בשם) \u0003ר' אליעזר: אין מבקרין לא חולי מעיים ולא חולי העין ולא\u0004 את אלה שיש להם \u0003מחושי הראש.\u0004 ומבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003חולי מעיים משום כיסופא\u0004 \u0005[בושה],\u0006 שהוא נזקק בכל פעם לצאת לנקביו, ולא נוח לו הדבר בגלל האורח. \u0003אלא חולי העין ומחושי הראש מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין מבקרים אותם?","ומשיבים: \u0003משום\u0004 הטעם שאמר \u0003רב יהודה,\u0004 ש\u0003אמר רב יהודה: דיבורא קשיא לעינא\u0004 \u0005[הדיבור קשה לעין]\u0006 \u0003ומעלי לאישתא\u0004 \u0005[ומועיל לקדחת].\u0006 ולכן, מי שיש לו כאבי עיניים או ראש — מוטב שלא ידבר, ואם מבקרים אותו יצטרך לדבר עם מבקריו, והדבר עלול להזיק לו. \u0003אמר רבא: האי אישתא\u0004 \u0005[קדחת זו],\u0006 \u0003אי לאו דפרוונקא דמלאכא דמותא\u0004 \u0005[אם לא ש\u0006היא \u0005השליח של מלאך המוות],\u0006 כלומר, שהיא גוררת אחריה חולי קשה עד כדי סכנת מוות, הייתי אומר עליה שהיא \u0003מעלי\u0004 \u0005[מעולה]\u0006"],["\u0003כחיזרא לדיקלי\u0004 \u0005[כמו הקוצים\u0006 שמקיפים סביב \u0005לדקל],\u0006 שהם שומרים אותו, אם היה החום בא \u0003חד לתלתין יומין\u0004 \u0005[אחת לשלושים יום],\u0006 \u0003וכי תירייקי לגופא\u0004 \u0005[וכמו סם רפואה לגוף].\u0006 \u0003רב נחמן בר יצחק אמר:\u0004 מוטב לו לאדם כשאין לו קדחת, \u0003לא היא ולא תירייקה\u0004 \u0005[רפואתה].\u0006","\u0003אמר רבה בר יונתן אמר רב יחיאל: ערסן יפה לחולה לרפואתו.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003ערסן\u0004 זה? \u0003אמר ר' יונתן: חושלא דשערי עתיקתא דריש נפיא\u0004 \u0005[שעורים ישנות קלופות שמתחילת הניפוי],\u0006 \u0003אמר אביי: בעיין בישולא כעין בישרא דתורא\u0004 \u0005[\u0006ו\u0005צריכות בישול כמו בשר שור],\u0006 כלומר, בישול רב. \u0003רב יוסף אמר:\u0004 ערסן הוא \u0003סמידי דשערי עתיקתא דריש נפיא\u0004 \u0005[סולת של שעורים ישנות שמתחילת הניפוי],\u0006 \u0003אמר אביי: בעיין בישולא כבשרא דתורא\u0004 \u0005[צריכות בישול כבשר שור].\u0006","\u0003אמר ר' יוחנן:\u0004 מי שחולה במחלת המעיים \u0003בורדם, אין מבקרים\u0004 אותו, \u0003ואין מזכירין שמו\u0004 מפני שיש בכך בושה לחולה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין מבקרים אותו? \u0003אמר ר' אלעזר: מפני שהוא כמעיין הנובע\u0004 שכל הזמן בשלשול. \u0003ואמר ר' אלעזר: למה נקרא שמו \"בורדם\" — לפי שהוא כמעיין הנובע\u0004 (בור— דם).","ושבים למשנתנו, שנאמר בה שמכל מקום מי שחבירו מודר ממנו הנאה \u0003ומרפאהו רפואת הנפש\u0004 אבל לא רפואת ממון. ומבררים: \u0003היכי קתני\u0004 \u0005[איך\u0006 בדיוק \u0005שנה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003\"רפואת נפש\"\u0004 כוונתו שמרפאהו \u0003בחנם, \"רפואת ממון\"\u0004 כוונתו \u0003בשכר, ליתני הכי\u0004 \u0005[שישנה כך]\u0006 במפורש: \u0003מרפאהו בחנם, אבל לא בשכר! אלא: \"רפואת נפש\"\u0004 כוונתה רפואת \u0003גופו, \"רפואת ממון\"\u0004 היא רפואת \u0003בהמתו. אמר ר' זוטרא בר טוביה אמר רב:\u0004 אף על פי שאסור ברפואת בהמתו של המודר ממנו הנאה, \u0003אבל אומר לו \"סם פלוני יפה לה\u0004 לבהמה, \u0003סם פלוני רע לה\",\u0004 שמאחר שאינו מטפל בה ממש, אין זה נקרא שמהנה אותו.","\u0003ורוחץ עמו\u0004 עם המודר ממנו הנאה \u0003באמבטי גדולה\u0004 שאין בה כל השפעה לכך שאף הוא נמצא באמבטי, \u0003אבל לא בקטנה,\u0004 שאם היא חמה מדי או קרה מדי גורם גוף נוסף הנמצא באמבטי למתן את מידת החום של המים, ונמצא שגורם לו הנאה. \u0003וישן עמו במטה.\u0004","\u0003ר' יהודה אומר:\u0004 מותר לישן עימו במטה \u0003בימות החמה,\u0004 שאין בכך הנאה כאשר נמצאים יחד, \u0003אבל לא בימות הגשמים, מפני שהוא מהנהו\u0004 במה שמחמם את המיטה. \u0003ומיסב עמו על המטה\u0004 אפילו בימות הגשמים, שאין בכך הנאה. \u0003ואוכל עמו על השולחן, אבל לא מן התמחוי\u0004 (כלי גדול) שאוכלים ממנו יותר מאדם אחד. שהרי אם משאיר עבור חבירו חלק מן האוכל, גורם לו בכך הנאה. \u0003אבל אוכל הוא עמו מן התמחוי החוזר,\u0004 שאם התמחוי סובב וחוזר שנית בין כל המסובים — יכול לאכול עימו ממנו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לא ירחץ עמו באמבטי, ולא ישן עמו במטה, בין גדולה בין קטנה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 במיטה \u0003גדולה בימות הגשמים, וקטנה בימות החמה מותר,\u0004 שאין בכך הנאה. \u0003רוחץ עמו באמבטי גדולה, ומזיע עמו בקטנה,\u0004 שאין נוכחותו מביאה תועלת לחבירו. \u0003אבל מיסב עמו על המטה ואוכל עמו על השולחן, אבל לא מן התמחוי. אבל אוכל הוא מן התמחוי החוזר. אמר ר' יוסי בר חנינא:\u0004 הכוונה היא \u0003מן התמחוי החוזר לבעל הבית,\u0004 שהמסובים אינם גומרים את כל המצוי בתמחוי, וכל מי שאוכל ממנו משאיר מקצת, ויש די לכולם.","\u0003לא יאכל עמו מן האבוס\u0004 (כלי אוכל) \u0003ש\u0004שמים \u0003לפני הפועלים, ולא יעשה עמו\u0004 עבודה \u0003באומן\u0004 (שורה אחת בכרם), אלו \u0003דברי ר' מאיר. וחכמים אומרים: עושה והוא ברחוק ממנו\u0004 ולא כשהוא קרוב לו, שיש בכך משום עזרה לו.","כשעובד אתו \u0003בקרוב — הכל לא פליגי דאסיר\u0004 \u0005[אינם חלוקים שאסור].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 במשנה הרי זה \u0003ברחוק\u0004 ממנו, \u0003ר' מאיר סבר: גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003רחוק משום קרוב, דקא מרפי לה לארעא קמיה\u0004 \u0005[ש\u0006בקרוב \u0005הוא מרפה את האדמה לפניו]\u0006 על ידי שעודר בה, ומיקל עליו. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים ]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006"],["\u0003המודר הנאה מחבירו לפני שביעית\u0004 (שנת השמיטה), כלומר, בשנה רגילה — \u0003אינו יורד\u0004 (נכנס) \u0003לתוך שדהו\u0004 של החבר, \u0003ואינו אוכל מן\u0004 הנטיעות \u0003הנוטות\u0004 כלפי חוץ לשדה, אפילו שאינו נכנס לתוך השדה. \u0003ובשביעית\u0004 שאז פירות האילנות הם הפקר לכל — \u0003אינו יורד לתוך שדהו\u0004 של חבירו \u0003אבל אוכל הוא מן הנטיעות הנוטות\u0004 לחוץ, שהרי בשנה זו הפירות אינם שייכים לחבירו. אם \u0003נדר הימנו\u0004 רק \u0003מאכל, לפני שביעית — יורד\u0004 בכל זמן \u0003לתוך שדהו,\u0004 שהרי מותר בהנאה ממנו, \u0003ואינו אוכל מן הפירות\u0004 לפי שאסר עצמו באכילה מפירותיו. \u0003ובשביעית —\u0004 גם \u0003יורד ו\u0004גם \u0003אוכל.\u0004","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 אם אמר \u0003\"נכסים אלו\u0004 אסורים \u0003עליך\u0004 בהנאה \u0003\"\u0004\u0003לפני\u0004 שהגיעה שנת ה\u0003שביעית — אין יורד לתוך שדהו, ואינו אוכל מן הנוטות אף על פי שהגיע\u0004 שנת ה\u0003שביעית.\u0004 שכיון שחל איסור על הפירות קודם לכן, אין האיסור פוקע בשביעית. \u0003ואם בשביעית\u0004 עצמה \u0003נדר — אין יורד לתוך שדהו, אבל אוכל מן הנוטות,\u0004 שהרי בשעה שהדירו אין הפירות שלו ולא היה יכול לאוסרם עליו.","\u0003ור' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 אחרת: אם אמר לחבירו \u0003\"נכסי\u0004 אסורים \u0003עליך\u0004 בהנאה \u0003\"\u0004\u0003לפני שביעית — אין יורד לתוך שדהו ואין אוכל מן הנוטות, הגיע\u0004 שנת ה\u0003שביעית — אינו יורד לתוך שדהו, אבל אוכל הוא את הנוטות\u0004 מפני שהם הפקר.","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 ש\u0005ב\u0006עקרון \u0005זה נחלקו],\u0006 ש\u0003רב ושמואל סברי\u0004 \u0005[סבורים]:\u0006 \u0003אדם אוסר דבר שברשותו אפילו לכשיצא מרשותו,\u0004 וכיון שאסר את הפירות לפני שביעית, אף כשהגיעה שנת השביעית והנכסים יצאו מרשותו, מכל מקום האיסור עדיין חל עליהם. \u0003ו\u0004אילו \u0003ר' יוחנן וריש לקיש סברי\u0004 \u0005[סבורים]:\u0006 \u0003אין אדם אוסר דבר שברשותו לכשיצא מרשותו,\u0004 ולכן מותר לאכול את הפירות בשביעית?","ותוהים: \u0003ותסברא\u0004 \u0005[וכי\u0006 יכול \u0005אתה לסבור כן]?\u0006 \u0003מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 \u0003אין אדם אוסר דבר שברשותו לכשיצא מרשותו?\u0004 ראשית, הדבר אינו עולה מתוך דבריהם, כי \u0003אם כן\u0004 סבורים ר' יוחנן וריש לקיש, \u0003ניפלגי\u0004 \u0005[שיחלקו]\u0006 \u0003ב\u0004אומר \u0003\"נכסים אלו\"\u0004 שלמרות שאמר \"אלו\" אין האיסור חל עליהם כאשר יוצאים מרשותו, בשביעית, \u0003וכל שכן ב\u0004אומר \u0003\"נכסי\",\u0004 שאז משמעות הדברים היא רק שאוסר עליו כל עוד הם נכסיו, ולא כשאינם ברשותו!","\u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003הא תנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]\u0006 ש\u0003אדם אוסר דבר שברשותו לכשיצא מרשותו, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לבנו \"קונם שאתה נהנה לי\",\u0004 אם \u0003מת\u0004 האב — \u0003יירשנו\u0004 הבן, שהרי אז אינו נהנה משל אביו, כיון שלאחר מותו אין לו עוד קנין בנכסיו. ואם אמר שהוא אוסר עליו את נכסיו \u0003\"בחייו ובמותו\",\u0004"],["\u0003אם מת\u0004 האב — \u0003לא יירשנו\u0004 הבן, משמע שיכול לאסור את נכסיו גם אחרי שייצאו מרשותו! ודוחים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דקא אמר ליה\u0004 \u0005[שאומר לו]\u0006 במפורש \u0003\"בחייו ובמותו\",\u0004 אבל אין מוכח מכאן שגם אם אמר סתם שאוסר נכסים אלו, שהם נאסרים גם לאחר שיצאו מרשותו.","אף שתירצנו קושי זה, \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 על הדברים מקושיה ראשונה: מפני מה לא נחלקו אף באומר \"נכסים אלו\"? \u0003אלא,\u0004 יש לחזור מהסבר זה וכך צריך לומר: כשאוסר \u0003ב\u0004לשון \u0003\"נכסים אלו\" — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שהאיסור חל על הנכסים גם כשיוצאים מרשותו. \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 הרי זה \u0003ב\u0004אומר \u0003\"נכסי\";\u0004","\u0003רב ושמואל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם אומר \u0003\"נכסים אלו\",\u0004 ו\u0003לא שנא\u0004 \u0005[שונה]\u0006 אם אומר \u0003\"נכסי\",\u0004 שבכולם \u0003אדם אוסר\u0004 אפילו לכשיצאו מרשותו. \u0003ור' יוחנן וריש לקיש סברי\u0004 \u0005[סבורים]\u0006 כי כשאומר \u0003\"נכסים\u0004 אלו \u0003\"\u0004— \u0003אדם אוסר\u0004 לעולם, אך כשהוא אומר \u0003\"נכסי\" — אין אדם אוסר\u0004 אלא כל זמן שהם ברשותו, ש\"נכסי\" משמעו — השייכים לי.","ושואלים: \u0003ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 כי \u0003לא שנא\u0004 \u0005[שונה]\u0006 כשאומר \u0003\"נכסים אלו\" ולא שנא\u0004 \u0005[שונה]\u0006 כשהוא אומר \u0003\"נכסי\"\u0004 ובכל מקרה יכול לאסור לכשיצאו מרשותו? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לחבירו \"קונם לתוך ביתך שאני נכנס\"\u0004 או שאומר \"קונם \u0003שדך שאני לוקח\u0004 (קונה)\", אם \u0003מת\u0004 בעל הבית \u0003או שמכרו לאחר — מותר,\u0004 שהרי לא נאסר בהם אלא כל זמן שהם ביתו ושדהו של אותו אדם. אבל אם אמר \u0003\"\u0004קונם \u0003לבית זה שאני נכנס\",\u0004 או שאמר: \u0003\"שדה זו שאני לוקח\",\u0004 גם אם \u0003מת\u0004 בעל הבית \u0003או שמכרו לאחר — אסור.\u0004 משמע שיש הבדל בדין אם אוסר את הנכס עצמו (\"בית זה\"), או שאומר \"נכסים של פלוני\" (\"ביתך\"), שאז האיסור הוא רק בזמן שהם ברשותו!","\u0003אלא,\u0004 יש לחזור מכל מה שאמרנו ולומר כך: \u0003כי אמרי\u0004 \u0005[כאשר אומרים]\u0006 \u0003ר' יוחנן וריש לקיש\u0004 את דבריהם שאין אדם אוסר נכסיו לכשיצאו מרשותו, הרי זה \u0003ב\u0004אומר ומפרש \u0003\"נכסי\", ורב ושמואל\u0004 אמרו שאוסר דווקא \u0003ב\u0004אומר \u0003\"נכסים אלו\", ו\u0004להלכה \u0003לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 שכל זוג חכמים דיבר במציאות אחרת.","שנינו במשנה: \u0003ובשביעית אין יורד לתוך שדהו,\u0004 אבל אוכל הוא מן הפירות הנוטים מחוץ לתחום שדהו. ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 ש\u0003אוכל מן הנוטות —\u0004 משום \u0003דפירי דהפקירא אינון\u0004 \u0005[שפירות של הפקר הם],\u0006 אם כן \u0003ארעא נמי אפקרה\u0004 \u0005[\u0006את \u0005הקרקע גם כן הפקירה]\u0006 התורה, שבשביעית הכל מותרים להיכנס ולאכול ומדוע אסור למודר להיכנס לשדה המדיר?!","\u0003אמר עולא:\u0004 כאן מדובר \u0003בעומדין\u0004 אותם \u0003אילנות\u0004 של פרי \u0003על הגבולים\u0004 של השדה, וכיון שיכול לאכול מפירותיהם גם בלא להיכנס לשדה — לא התירו לו להיכנס לשדה. \u0003ר' שמעון בן אליקים אמר:\u0004 אפילו כשהיו האילנות עומדים בתוך השדה אסור לו לרדת לשדה, \u0003גזירה שמא ישהא בעמידה\u0004 בשדה שלא לצורך אכילה, ודבר זה לא הותר לו אפילו בשביעית.","\u0003המודר הנאה מחבירו — לא ישאילנו\u0004 חבירו \u0003ולא ישאל ממנו, לא ילונו ולא ילוה ממנו, ולא ימכור לו ולא יקח\u0004 (יקנה) \u0003ממנו.\u0004"],["שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 האיסור ש\u0003לא ילונו\u0004 חבירו מובן — משום \u0003דקא מהני ליה\u0004 \u0005[ש\u0006הוא \u0005מהנה אותו]\u0006 בכך. \u0003אלא לא ילוה הימנו, מאי קא מהני ליה\u0004 \u0005[מה מהנה אותו]\u0006 חבירו בזה? \u0003ו\u0004אפילו \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לא ילוה הימנו ולא יקח הימנו\u0004 משום \u0003דקמיתהני מיניה\u0004 \u0005[שהוא\u0006 \u0005נהנה ממנו],\u0006 שאפשר לומר שהמודר מבטיח את כספו על ידי ההלוואה, או שמוכר דבר שקשה לו למוכרו באופן אחר, \u0003אלא לא ישאל הימנו מאי קא מיתהני מיניה\u0004 \u0005[מה\u0006 הוא \u0005נהנה ממנו]\u0006 שהרי השואל מחזיר לו את אותו חפץ עצמו!","\u0003אמר ר' יוסי בר' חנינא:\u0004 יש לפרש \u0003כגון שנדרו הנאה זה מזה,\u0004 ומשום כך מובן מדוע לא ישאל ולא ישאיל וכו'. \u0003אביי אמר:\u0004 אפשר להסביר כמשמעה של המשנה שרק אחד אסור בהנאה, אלא \u0003גזירה\u0004 היא שגזרו חכמים שלא \u0003לשאול\u0004 מן המודר ממנו הנאה \u0003משום להשאיל,\u0004 שאם יתירוהו לשאול יש לחשוש שמא יבוא להשאיל, כדרך שאנשים נוהגים זה עם זה, ולכן גזרו שלא יהיה ביניהם משא ומתן כל עיקר, \u0003וכן בכולהו\u0004 \u0005[בכולם]\u0006 בהלוואה ובמכר \u0003גזירה\u0004 היא, כדי שלא יגיע לבסוף ליהנות ממנו.","\u0003אמר לו\u0004 לחבירו: \u0003\"השאילני פרתך\". אמר לו\u0004 החבר: \u0003אינה פנויה.\u0004 כעס המבקש ו\u0003אמר: \"קונם שדי שאני חורש בה\u0004 בפרה זו \u0003לעולם\".\u0004 הרי \u0003אם היה דרכו לחרוש\u0004 בעצמו — \u0003הוא אסור\u0004 מעתה לחרוש שדהו בפרה זו, \u0003וכל\u0004 שאר בני \u0003אדם מותרים\u0004 לחרוש בה עבורו. \u0003ואם אין דרכו לחרוש\u0004 אלא אחרים חורשים בשבילו — \u0003הוא וכל אדם אסורין,\u0004 שזו היתה כוונת הנודר, שאסר על עצמו הנאת חרישה בפרה זו.","ענין אחר; \u0003המודר הנאה מחבירו ואין לו\u0004 למודר \u0003מה יאכל,\u0004 והחבר אינו יכול לתת לו, שהרי אסור הלה בנדר מליהנות לו. \u0003הולך\u0004 החבר \u0003אצל החנוני ואומר\u0004 לו: \u0003איש פלוני נודר ממני הנאה ואיני יודע מה אעשה.\u0004 והחנווני מבין את כוונתו, \u0003והוא\u0004 החנווני \u0003נותן לו\u0004 למודר שאין לו מה לאכול, \u0003ובא\u0004 אחר כך החנווני \u0003ונוטל\u0004 את המגיע לו \u0003מזה\u0004 שאמר לו.","כיוצא בזה, אם \u0003היה ביתו\u0004 של המודר צריך \u0003לבנות,\u0004 או \u0003גדרו לגדור,\u0004 או \u0003שדהו לקצור\u0004 וזקוק לפועלים ואין כסף בידו לשוכרם, \u0003הולך\u0004 החבר \u0003אצל הפועלים ואומר: איש פלוני מודר ממני הנאה ואיני יודע מה אעשה. והן\u0004 הפועלים \u0003עושין עמו\u0004 (עובדים אצלו), \u0003ובאין ונוטלין שכר\u0004 על עבודתם \u0003מזה\u0004 שאמר להם.","\u0003היו מהלכין בדרך ואין לו\u0004 למודר \u0003מה יאכל — נותן\u0004 החבר \u0003לאחד לשום\u0004 (לשם) \u0003מתנה, והלה\u0004 המודר \u0003מותר בה.\u0004 שעכשיו לא משל המודר הוא נהנה, אלא משל אדם אחר. \u0003אם אין עמהם אחר\u0004 אלא היו שם רק שניהם — \u0003מניח\u0004 את האוכל \u0003על הסלע או על הגדר ואומר: הרי הן מופקרים לכל מי שיחפוץ,\u0004 וכיון שכך, שוב אינם שלו, \u0003והלה\u0004 המודר \u0003נוטל ואוכל. ור' יוסי אוסר\u0004 בכגון זה.","שנינו במשנה שאם היו המודר וחבירו לבדם, ורצה החבר לתת אוכל למודר, יכול לעשות זאת על ידי שמפקיר את האוכל, ור' יוסי אוסר. \u0003אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי? קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003הפקר\u0004 דינו \u0003כמתנה\u0004 לדיני קנין. \u0003מה מתנה\u0004 אין קניינה נגמר \u0003עד דאתיא\u0004 \u0005[שמגיעה]\u0006 \u0003מרשות נותן לרשות מקבל,\u0004 וכל עוד לא זכה בה המקבל אינה נחשבת כמתנה, \u0003אף הפקר — עד דאתיא\u0004 \u0005[שמגיע]\u0006 \u0003לרשות זוכה,\u0004 שאין החפץ המופקר נחשב כיוצא לגמרי מרשות בעליו עד שיזכה בו אדם אחר. ובמקרה המתואר במשנה, שעדיין לא נותק קשר הבעלות בין החפץ ובין הנותן, אסור הלה לזכות בו שהרי נהנה ממנו במישרין.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אבא,\u0004 שנינו בברייתא: \u0003והלה נוטל ואוכל ור' יוסי אוסר. אמר ר' יוסי: אימתי\u0004 אומר אני שהוא אסור — \u0003בזמן שנדרו קודם להפקירו,\u0004 שאז חל האיסור מתחילה על כל רכושו, גם על מה שהפקיר לאחר מכן."],["\u0003אבל אם היה הפקירו קודם לנדרו — הרי זה מותר. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שטעמו של ר' יוסי הוא שאין החפץ יוצא מרשות המפקיר \u0003עד דאתי\u0004 \u0005[שבא]\u0006 \u0003לרשות זוכה,\u0004 אם כן, \u0003מה לי\u0004 אם היה \u0003נדרו קודם להפקירו מה לי הפקירו קודם לנדרו?\u0004 הרי בכל מקרה לא יצא החפץ מרשות בעליו, והרי המודר נהנה ממנו!","ומשיבים: \u0003הוא,\u0004 ר' אבא, \u0003מותיב לה\u0004 \u0005[היה מקשה אותה\u0006 קושיה\u0005]\u0006 \u0003והוא\u0004 עצמו \u0003משני לה\u0004 \u0005[היה מתרץ אותה],\u0006 שאין ההבדל בין הדברים משום דיני ההפקר אלא משום הנדר עצמו, ש\u0003כל הנודר אין דעתו על מה שהפקיר.\u0004 ולכן, אם נדר לאחר שהפקיר לא התכוון לכלול בתוך הנדר את מה שהפקיר, ומשום כך לא חל על כך האיסור. ואם הפקיר לאחר שנדר, כן התכוון לכלול את מה שהפקיר בתוך נדרו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא:\u0004 אדם שנטה למות (\"שכיב מרע\") וציווה לחלק את כל נכסיו, אם עמד מחוליו — חוזר בו מכל מתנותיו. אבל אם נתן רק חלק מנכסיו ושייר מקצתם — אינו יכול לחזור בו. ובמקרה שהיה חולה ונתן נכסיו לשנים, ואמר \u0003\"מקצתן לראשון וכולן\u0004 (כל השאר) \u0003לשני\",\u0004 אם הבריא לאחר מכן — ה\u0003ראשון קנה\u0004 נכסים שנתן לו, שהרי בשעה שנתן לו ציווה רק חלק מנכסיו, ובמתנה כזו אינו יכול לחזור בו.","אבל ה\u0003שני לא קנה,\u0004 שהרי השני עמד לקבל את כל שאר הנכסים בלא כל שיור, ואם הבריא — יכול לחזור בו ממה שציווה לתת לו. וממה שאמרו שהשני לא קנה, עולה, כי למרות שלא זכה בה הראשון (שהרי אין מתנה זו נגמרת אלא עם מותו של המצוה), מכל מקום יצאה כבר מרשות הנותן. ושלא כדברי ר' יוחנן שאין הקנין במתנה נגמר עד שתגיע לידי הזוכה!","\u0003אלא אמר רבא: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' יוסי: גזירה\u0004 היא שגזרו חכמים בהדיר את חבירו הנאה מנכסיו ואחר כך הפקיר נכסיו, \u0003משום מתנת בית חורון.\u0004 שהיה מעשה ביישוב בית חורון במתנה שנתן אדם לחבירו רק כדי להערים על הנדר, ואמרו חכמים שהערמה כזו אסורה. ואף כאן, כיון שמפקיר רק לשם הערמה על הנדר — אסור.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003המפקיר את שדהו, כל שלשה ימים\u0004 מאז ההפקר — \u0003יכול לחזור בו\u0004 וכאילו לא הפקיר כלל, \u0003מכאן ואילך — אין יכול לחזור בו\u0004 והרי זה הפקר, וכל הזוכה מן ההפקר קונה את השדה."],["\u0003אמר \"תהא שדה זו מופקרת ליום אחד\",\u0004 או שהפקירה \u0003לשבת\u0004 (שבוע) \u0003אחת,\u0004 או \u0003לחדש אחד,\u0004 או \u0003לשנה אחת,\u0004 או \u0003לשבוע\u0004 (שבע שנים) \u0003אחת\" עד שלא זכה בה\u0004 בשדה זו, \u0003בין הוא\u0004 המפקיר עצמו \u0003בין\u0004 אדם \u0003אחר — יכול\u0004 המפקיר \u0003לחזור בו,\u0004 ולומר שהוא מבטל את ההפקר. \u0003משזכה בה\u0004 בשדה — \u0003בין הוא\u0004 עצמו \u0003בין אחר — אין יכול לחזור בו.\u0004 וברייתא זו תמוהה, שהרי יש לפרש לכאורה ש\u0003רישא רבנן\u0004 \u0005[תחילתה\u0006 כשיטת \u0005חכמים]\u0006 שההפקר נגמר באופן חד־צדדי, ואינו תלוי בזכיה של אחר, ואילו \u0003סיפא\u0004 \u0005[סופה]\u0006 שיטת \u0003ר' יוסי\u0004 שאין ההפקר נגמר אלא אם כן זכה בו אדם!","\u0003אמר עולא:\u0004 אפשר לפרש כי \u0003סיפא נמי רבנן\u0004 \u0005[סופה גם כן\u0006 כשיטת \u0005חכמים]\u0006 \u0003היא.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003עד שלא זכה בה בין הוא בין אחר, יכול לחזור בו?\u0004 הרי כבר הפקיר את השדה! ואף שהוא עצמו יכול לזכות בו, איך יכול לחזור בו מן ההפקר? ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 הפקר ל\u0003שנה ו\u0004ל\u0003שבוע\u0004 ש\u0003לא שכיחי\u0004 \u0005[מצוי]\u0006 הוא, וכיון שמתחילה הגביל את זמן ההפקר, משמע שמשמר לעצמו זכויות מסויימות, ולכן אף יכול לחזור בו.","\u0003ריש לקיש אמר: מדסיפא\u0004 \u0005[מ\u0006כיון \u0005שסופה]\u0006 של הברייתא הוא כשיטת \u0003ר' יוסי — רישא נמי\u0004 \u0005[תחילתה גם כן]\u0006 יש לפרשה כשיטת \u0003ר' יוסי. ורישא\u0004 \u0005[ותחילתה]\u0006 שנאמר בה שאינו יכול לחזור בו לאחר שלושה ימים, \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 — שתקנת חכמים היא שאם כך \u0003לא לישתכח\u0004 \u0005[תימצא]\u0006 \u0003תורת הפקר,\u0004 שאם יכול לחזור בו לעולם, יימצא שאין הפקר בעולם, אפילו כשיזכה בו אחר, שלא יבדילו בין זכה בו אחר ללא זכה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו מיום הראשון נמי ליהוי\u0004 \u0005[גם כן שיהא]\u0006 \u0003הפקר\u0004 מוחלט, ולא יוכל לחזור בו! \u0003אמר רבה:\u0004 הטעם שאין ההפקר נחשב מן היום הראשון הוא \u0003מפני הרמאין,\u0004 ש\u0003מפקירין והדרין בהון\u0004 \u0005[וחוזרים בהם]\u0006 וכל ההפקר הזה הוא רק כדי להפקיע את השדה מחובת המעשר, לפי שהפקר פוטר ממעשרות, ואחר כך חוזרים בהם מיד, ומשום כך תיקנו שלא יחול דין הפקר עד לאחר שלושה ימים.","ושואלים: \u0003אבל\u0004 האם לשיטה זו \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003לא הוי\u0004 \u0005[אין זה]\u0006 \u0003הפקר\u0004 לדעת ר' יוסי, ואם יחזור בו אפילו לאחר שלושה ימים ויבטל את ההפקר בכל עת, בטל ההפקר מעיקרו?"],["\u0003ודלמא אתי לעשורי\u0004 \u0005[ושמא יבוא לעשר]\u0006 \u0003מן החיוב על הפטור, ומן הפטור על החיוב.\u0004 שאם מדין תורה אין זה הפקר, הריהו חייב במעשרות, וכיון שתיקנו שיהא דינו כהפקר סבורים אנשים שהוא הפקר ממש ולא יפרישו ממנו מעשרות. או שיחשבו שדין הפרשה ממנו הוא רק מדברי סופרים ויבואו להפריש עליו ממה שאינו חייב בהפרשה מדין תורה, או להיפך, ונמצא שלא יהיו הפירות מעושרים ומתוקנים כראוי!","ומשיבים: \u0003דאמרינן ליה\u0004 \u0005[שאנו אומרים לו]:\u0006 \u0003כי מעשרת\u0004 \u0005[כאשר אתה מעשר]\u0006 — \u0003עשר מיניה וביה\u0004 \u0005[ממנו ובו].\u0006 כלומר, אל תעשר ממקום אחר, אלא מתוך השדה הזה על עצמו, ואז אין חשש בדבר.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003המפקיר את כרמו, ולשחר\u0004 (בבוקר) \u0003עמד\u0004 והקדים הוא עצמו \u0003ובצרו —\u0004 הרי זה \u0003חייב בפרט ובעוללות ובשכחה ובפאה,\u0004 כיון שכל החיובים הללו חלים על זה שקוצר את השדה ולא על בעליו. \u0003ו\u0004אולם \u0003פטור\u0004 הוא \u0003מן המעשר,\u0004 שכיון שהיה הכרם הפקר — כבר בטלה מפירותיו חובת המעשר.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003עולא\u0004 בהסבר הברייתא לעיל, אפשר להסביר כי ברייתא זו \u0003דרבנן קתני לה\u0004 \u0005[ל\u0006שיטת \u0005חכמים שנה אותה\u0006 התנא\u0005]\u0006 \u0003ודאורייתא קתני לה\u0004 \u0005[ומדין תורה שנה אותה],\u0006 שלדעת חכמים מיד כשמפקיר — חל ההפקר מדין תורה (אף שתיקנו שמדברי סופרים לא יחול לגמרי עד שלושה ימים), ופטורה השדה מן המעשר, וברייתא זו דנה בדבר על פי החיוב מן התורה. \u0003אלא ל\u0004דעת \u0003ריש לקיש, אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור\u0004 בכגון זה \u0003מן המעשר?\u0004 הרי לא היה זה הפקר כלל עד לאחר שלושה ימים, בין מדברי תורה ובין מדברי סופרים!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה ריש לקיש \u0005לומר]\u0006 \u0003לך: כי אמרי אנא\u0004 \u0005[כאשר אמרתי אני],\u0006 הרי זה \u0003ל\u0004דעת \u0003ר' יוסי,\u0004 שאין הפקר יוצא מרשות בעליו עד שיזכה בו אחר, ואילו \u0003הא\u0004 \u0005[\u0006המשנה \u0005הזו]\u0006 האומרת שחל ההפקר אפילו מן הלילה לבוקר — זו \u0003רבנן\u0004 \u0005[\u0006שיטת \u0005חכמים]\u0006 \u0003היא,\u0004 הסבורים שבעצם ההפקרה יוצא הדבר מרשותו."],["\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: \u0003הא\u0004 \u0005[זה]\u0006 שאינו הפקר גמור עד שיזכו בו — הרי זה במקרה \u0003דאפקריה באנפי תרין\u0004 \u0005[שהפקירו בפני שנים]\u0006 בלבד. \u0003והא\u0004 \u0005[וזה]\u0006 שנאמר שהוא הפקר גמור הרי זה במקרה \u0003דאפקריה באפי תלתא\u0004 \u0005[שהפקירו בפני שלושה].\u0006 ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: כל המפקיר בפני שלשה — הוי\u0004 \u0005[הריהו]\u0006 \u0003הפקר, בפני שנים — לא הוי\u0004 \u0005[אינו]\u0006 \u0003הפקר.\u0004","\u0003ור' יהושע בן לוי אמר: דבר תורה אפילו באחד\u0004 שמפקיר בפניו — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003הפקר, ומה טעם אמרו\u0004 חכמים שיהא הפקר \u0003בשלשה —\u0004 לא מעצם דין ההפקר, אלא \u0003כדי שיהא אחד זוכה ושנים מעידין\u0004 גם על ההפקר וגם על הזכיה.",""],["\u0003השותפין שנדרו הנאה זה מזה —\u0004 \u0003אסורין ליכנס לחצר\u0004 המשותפת לשניהם, שהרי כל אחד יש לו חלק בה והאחר אסור ליהנות מחלקו. \u0003ר' אליעזר בן יעקב אומר:\u0004 שניהם מותרים, כי אפשר לומר שכיון שלכל אחד יש חלק בחצר, הרי \u0003זה נכנס לתוך\u0004 חלקו \u0003שלו, וזה נכנס לתוך שלו.\u0004"],["\u0003ו\u0004מכל מקום, לדעת כולם, \u0003שניהם אסורים להעמיד ריחים ותנור\u0004 בחצר המשותפת \u0003ולגדל\u0004 בה \u0003תרנגולים.\u0004","\u0003היה\u0004 רק \u0003אחד מהם מודר הנאה מחבירו —\u0004 \u0003לא יכנס לחצר,\u0004 שהרי החצר היא גם של חבירו. \u0003ר' אליעזר בן יעקב אומר: יכול הוא לומר לו: לתוך שלי אני נכנס, ואיני נכנס לתוך שלך. ו\u0004מכל מקום \u0003כופין את הנודר למכור את חלקו,\u0004 כדי שלא יביא את חבירו לידי איסור.","\u0003היה אחד מן השוק מודר באחד מהם הנאה —\u0004 \u0003לא יכנס לחצר,\u0004 שהרי החצר שייכת גם לזה שהוא אסור בהנאתו. \u0003ר' אליעזר בן יעקב אומר: יכול לומר לו: לתוך\u0004 חלקו \u0003של חבירך אני נכנס, ואיני נכנס לתוך\u0004 החלק \u0003שלך,\u0004 שלא הכל שלך הוא.","\u0003המודר הנאה מחבירו ויש לו מרחץ\u0004 או \u0003בית הבד מושכרין בעיר\u0004 שהכל יכולים להשתמש בהם, \u0003אם יש לו\u0004 למדיר, \u0003בהן תפיסת יד,\u0004 שיש לבעלים הראשונים עוד איזו זכות במקום, שלא השכיר את המקום לגמרי אלא השאיר לעצמו אלו זכויות — \u0003אסור\u0004 למודר ההנאה להשתמש, אם \u0003אין לו בהן תפיסת יד —\u0004 \u0003מותר.\u0004","\u0003האומר לחבירו: \"קונם לביתך שאני נכנס ושדך שאני לוקח\u0004 (קונה) \u0003\",\u0004 אם \u0003מת או שמכרו\u0004 את הבית \u0003לאחר —\u0004 \u0003מותר,\u0004 שהרי שוב אין זה שדהו או ביתו. אבל אם אמר \u0003\"קונם בית זה שאני נכנס\",\u0004 או שאמר \u0003\"\u0004קונם \u0003שדה זו שאני לוקח\",\u0004 גם אם \u0003מת\u0004 בעל הבית \u0003או שמכרו לאחר —\u0004 \u0003אסור.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 במשנה שנינו כי \u0003ב\u0004מקרה ש\u0003נדרו\u0004 השותפין זה מזה \u0003פליגי\u0004 \u0005[חלוקים]\u0006 חכמים ור' אליעזר בן יעקב, ואם כן יש לשאול: אם לא נדרו הנאה זה מזה, אלא \u0003הדירו זה את זה מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 כי דווקא \u0003בנדרו הוא דפליגי\u0004 \u0005[ש\u0006הם \u0005חלוקים],\u0006 \u0003אבל בהדירו זה את זה מודו ליה רבנן\u0004 \u0005[מודים לו חכמים]\u0006 \u0003לר' אליעזר בן יעקב,\u0004 ומדוע? — \u0003דכי\u0004 \u0005[ש\u0006הרי \u0005כמו]\u0006 \u0003אנוסין דמו\u0004 \u0005[נחשבים].\u0006 שהרי החבר הוא שאסר עליו, והוא עצמו אינו אחראי לאיסור, ולכן יכול כל אחד לומר שמחלקו שלו הוא נהנה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אפילו ב\u0004מקרה ש\u0003הדירו זה את זה\u0004 הנאה \u0003פליגי רבנן\u0004 \u0005[חלוקים חכמים]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מהמשך דברי המשנה, ששנינו: \u0003היה אחד מהן מודר הנאה מחבירו, ו\u0004בכל זאת \u0003פליגי רבנן\u0004 \u0005[חלוקים חכמים]\u0006 ואוסרים אותו! ודוחים: אל תדייק כך במשמעות לשון \"מודר\" אלא \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003נדור מחבירו הנאה,\u0004 שהוא עצמו נדר, וגרם איסור לעצמו.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להבין, \u0003דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנה בסופה]\u0006 של אותה הלכה: \u0003וכופין את הנודר למכור את חלקו. אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמדובר במקרה ש\u0003נדר הוא\u0004 עצמו הנאה מחבירו, \u0003היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 \u0003כופין,\u0004 שכיון שהוא יצר את הבעיה, כופים אותו לפתור אותה. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שמדובר במקרה \u0003דאדריה\u0004 \u0005[ש\u0006חבירו \u0005הדיר אותו]\u0006 הנאה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003כופין אותו? הא מינס אניס\u0004 \u0005[הרי אנוס\u0006 הוא\u0005]\u0006 ומדוע נכריח אותו למכור את חלקו?","\u0003אמר רבה אמר זעירי:\u0004"],["\u0003מחלוקת\u0004 זו של ר' אליעזר בן יעקב וחכמים היא כאשר החצר היא גדולה למדי \u0003שיש בה כדי חלוקה\u0004 (שיקבל כל אחד לאחר החלוקה לפחות ארבע אמות מרובעות), ואז יש מקום לומר שלכל אחד מהם יש בכוח חלק מוגדר בחצר, והשותף האחר אסור באותו חלק. \u0003אבל\u0004 אם היתה זו חצר קטנה, ש\u0003אין בה כדי חלוקה —\u0004 \u0003דברי הכל מותר,\u0004 שכל חלק בה שייך לשניהם, וכל אחד מהם יכול לומר שהוא נכנס לתוך שלו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 לרבה: \u0003הרי בית הכנסת\u0004 ששייך לרבים ש\u0003כמי שאין בו כדי חלוקה דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שהרי אי אפשר לומר שבית הכנסת יכול להתחלק ולכל מתפלל חלק לעצמו, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 אנשים שנדרו הנאה זה מזה — \u0003שניהן אסורין בדבר של אותה העיר,\u0004 כגון בית כנסת!","\u0003אלא אמר רב יוסף:\u0004 צריך לומר שכך \u0003אמר זעירי: מחלוקת\u0004 ר' אליעזר בן יעקב וחכמים היא כ\u0003שאין בה\u0004 בחצר \u0003כדי חלוקה, אבל\u0004 אם \u0003יש בה כדי חלוקה —\u0004 \u0003דברי הכל אסור.\u0004","\u0003אמר רב הונא: הלכה כ\u0004שיטת \u0003ר' אליעזר בן יעקב, וכן אמר ר' אלעזר: הלכה כ\u0004שיטת \u0003ר' אליעזר בן יעקב.\u0004","שנינו במשנה ש\u0003המודר הנאה מחבירו ויש לו שם מרחץ\u0004 או בית הבד מושכרים בעיר, אם יש לבעלים תפיסת יד בהם — אסור המודר בהם. ושואלים: \u0003וכמה\u0004 היא \u0003תפיסת יד\u0004 זו האוסרת את הכניסה על המודר? \u0003אמר רב נחמן:\u0004 כגון שנוטל המשכיר חלק מהרווחים של המרחץ \u0003למחצה לשליש ולרביע. אבל בבציר\u0004 \u0005[בפחות\u0006 מכן\u0005]\u0006 — \u0003לא\u0004 שאין חלק קטן כזה נחשב כבעלות. \u0003אביי אמר: אפילו בבציר\u0004 \u0005[בפחות]\u0006 משיעור זה — \u0003אסור. היכי דמי דשרי\u0004 \u0005[איך זה בדיוק שמותר]\u0006 — ש\u0003מקבל בטסקא\u0004 \u0005[בשכר],\u0006 כלומר, שהמשכיר מעביר לשוכר לגמרי את כל רשותו, ואינו מקבל אלא שכר קצוב בכל שנה, שאז אפשר לומר שסילק עצמו לגמרי מאותו מקום."],["שנינו במשנה: \u0003האומר לחבירו\u0004 \"קונם לביתך שאני נכנס\" או שאמר לו \"קונם שדך שאני לוקח\", אם יצא הבית מרשות בעליו — מותר בו. אך אם אמר \"קונם בית זה שאני נכנס\" הרי זה אסור בו לעולם. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אבימי\u0004 שאלה זו: אם הדיר את חבירו ואמר \u0003\"קונם לבית זה שאתה נכנס\",\u0004 אם \u0003מת או שמכרו לאחר מהו\u0004 דינו? האם נאמר ש\u0003אדם אוסר\u0004 על חבירו \u0003דבר שברשותו\u0004 גם \u0003לכשיצא\u0004 אותו הדבר לאחר מכן \u0003מרשותו, או לא?\u0004","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לכך ממה ששנינו: \u0003האומר לבנו \"קונם שאי אתה נהנה לי\", ומת\u0004 האב — \u0003יירשנו\u0004 הבן. ואם אסרו האב בלשון \u0003\"בחייו ובמותו\" ומת —\u0004 \u0003לא יירשנו. שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003אדם אוסר\u0004 על חבירו \u0003דבר שברשותו\u0004 גם \u0003לכשיצא מרשותו\u0004 לאחר מיתה, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ב\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה: האומר \u0003\"קונם פירות האלו עלי\",\u0004 או שאמר \u0003\"קונם הן על פי\",\u0004 או \u0003\"קונם הן לפי\" —\u0004 \u0003אסור\u0004 לא רק בהם, אלא גם \u0003בחילופיהן,\u0004 שאם מחליפים אותם בדבר אחר — גם הוא אסור, \u0003ובגידוליהן\u0004 שאם היה זה עץ וצמחו בו פירות — אסור גם בהם.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: אמר \"קונם פירות האלו על פלוני\", מהו\u0004 שיהא פלוני זה אסור \u0003בחילופיהן? מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי \u0003גבי דיליה\u0004 \u0005[לגבי עצמו],\u0006 \u0003הואיל ואדם אוסר\u0004 (יכול לאסור) \u0003פירות חבירו על עצמו\u0004 אף שאינם כעת ברשותו, באותו אופן \u0003אדם אוסר דבר שלא בא לעולם על עצמו,\u0004 ונאסר לא רק בדבר שנדר ממנו, אלא גם בחילופיו ובגידוליו שאינם מצויים כעת בעולם. אבל \u0003גבי חבירו, הואיל ואין אדם אוסר פירות חבירו על חבירו,\u0004 שמא נאמר גם ש\u0003אין אדם אוסר דבר שלא בא לעולם על חבירו.\u0004"],["\u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר \u0003משום\u0004 ש\u0003חילופין כגידולין דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 ולכן \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003הוא ולא שנא\u0004 \u0005[שונה]\u0006 \u0003חברו,\u0004 שכיון שהדבר נובע ובא מן הדבר האסור, נשאר האיסור במקומו, גם אם החליף אותו.","\u0003אמר רב אחא בר מניומי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לכך ממה ששנינו: \u0003האומר לאשתו \"קונם שאני נהנה ליך\u0004 (לך) \u0003\"\u0004ולכן אינה יכולה להתפרנס ממנו, כדי שתוכל להתקיים תהא \u0003לווה\u0004 כסף לפרנסתה, \u0003ובעלי חובין\u0004 שלה \u0003באין ונפרעין\u0004 חובותיה מן הבעל. ונברר: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003בעלי חובין נפרעין\u0004 חובותיה מן הבעל? הרי בסופו של דבר היא נהנית מבעלה שפורע את חובה — \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום\u0004 שאנו אומרים ש\u0003חילופין לאו\u0004 \u0005[אינם]\u0006 \u0003כגידולין דמי\u0004 \u0005[נחשבים]\u0006 ולכן יכולה היא ללוות ולקבל בעקיפין את הממון מבעלה כיון שאינה נהנית במישרין ממנו, אלא בדבר שהוחלף?","\u0003אמר רבא:\u0004 מכאן אין ראיה, כי \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לכתחילה הוא\u0004 ש\u0003לא\u0004 ייהנה בחילופיו של דבר שנאסר בנדר, \u0003ואי עבד\u0004 \u0005[ואם עשה]\u0006 — \u0003עבד\u0004 \u0005[עשה].\u0006 ואף לגבי האשה, כיון שאין לה דרך אחרת למחייתה — מותר.","\u0003אלא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממקום אחר: \u0003המקדש\u0004 אשה \u0003ב\u0004פירות של \u0003ערלה —\u0004 \u0003אינה מקודשת,\u0004 כי הפירות אסורים בהנאה, ונמצא שאין להם כל ערך, ואין קידושין חלים אלא בשווה פרוטה. אבל אם \u0003מכרן,\u0004 את הפירות הללו, \u0003וקידש בדמיהן —\u0004 \u0003הרי זו מקודשת.\u0004 משמע שאף שמקור הכסף היה אסור בהנאה, מכל מקום חילופיו אינם אסורים. ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לכתחילה הוא\u0004 ש\u0003לא\u0004 יהנה מהחליפים, \u0003ואי עבד\u0004 \u0005[ואם עשה]\u0006 וקידש אשה בהם — \u0003עבד\u0004 \u0005[עשה]\u0006 ומקודשת, ואין לפתור מכאן את הבעיה שהעמדנו.","אם אדם אומר לחבירו \u0003\"הריני עליך חרם\",\u0004 כלומר, כל רכושי יהיה אסור עליך כחרם — הרי \u0003המודר,\u0004 כלומר חבירו, \u0003אסור\u0004 ליהנות מן הנכסים. ואם אמר \u0003\"הרי את עלי חרם\" —\u0004 \u0003הנודר אסור\u0004 בנכסיו של חבירו. אם אמר \u0003\"הריני עליך ואת עלי\u0004 חרם \u0003\"\u0004— \u0003שניהם אסורין\u0004 זה בנכסי זה, \u0003ושניהם מותרין בדבר של עולי בבל,\u0004 כלומר, במה שהוא רכוש כלל האומה, ואינו נחשב כחלקו של שום אדם פרטי,"],["\u0003ואסורים בדבר של אותה העיר,\u0004 כיון שהוא נחשב כשייך בשותפות לכל בני העיר. \u0003ואיזהו דבר של עולי בבל\u0004 שאפשר לומר עליו שהוא שייך לכלל הציבור — \u0003כגון הר הבית, והעזרות, והבור\u0004 של מים \u0003שבאמצע הדרך. ואיזהו דבר של אותה העיר —\u0004 \u0003כגון הרחבה\u0004 (הכיכר שבעיר), \u0003ו\u0004בית \u0003המרחץ\u0004 שבה, \u0003ובית הכנסת, והתיבה\u0004 (ארון הקודש), \u0003והספרים\u0004 (ספרי תורה). \u0003והכותב חלקו\u0004 בדבר של אותה העיר \u0003לנשיא,\u0004","\u0003ר' יהודה אומר: אחד,\u0004 כלומר, הוא הדין בש \u0003כותב\u0004 חלקו \u0003לנשיא, ואחד\u0004 בש \u0003כותב להדיוט.\u0004 אלא \u0003מה בין כותב לנשיא לכותב להדיוט? שהכותב לנשיא אין צריך לזכות\u0004 לו את חלקו על ידי מעשה של קנין, והכותב \u0003להדיוט צריך לזכות\u0004 לו. \u0003וחכמים אומרים: אחד זה ואחד זה צריכין לזכות, לא דברו\u0004 בענין של מזכה \u0003לנשיא אלא בהוה,\u0004 שכך היו עושים. \u0003ר' יהודה אומר: אין אנשי גליל צריכין לכתוב\u0004 את חלקם לנשיא, לפי \u0003שכבר כתבו אבותיהן על ידיהן\u0004 (עבורם). שאמרו שכל נכסי הציבור נחשבים כשייכים לנשיא.","על מה ששנינו \"והכותב חלקו לנשיא\", תוהים: אם עושה כן, \u0003אמאי מיתסר\u0004 \u0005[מדוע נאסר]?\u0006 \u0003אמר רב ששת: הכי קתני\u0004 \u0005[כך שנה],\u0006 כך צריך להבין את המשנה: \u0003ומה תקנתן\u0004 שלא ייאסרו בנכסי העיר — \u0003יכתבו חלקן לנשיא.\u0004","\u0003ר' יהודה אומר: אחד כותב לנשיא ואחד כותב להדיוט, ומה בין כותב לנשיא לכותב להדיוט? הכותב לנשיא אין צריך לזכות, והכותב להדיוט צריך לזכות. וחכמים אומרים: אחד זה ואחד זה צריכים לזכות, לא דברו בנשיא אלא בהוה\u0004 שכך רגילים היו לעשות.","שנינו במשנה ש\u0003ר' יהודה אומר: אין אנשי גליל צריכין לזכות,\u0004 לפי \u0003שכבר כתבו אבותיהן על ידיהן. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה\u0004 \u0003אומר: אנשי גליל קנטרנין\u0004 (אנשי קטטה ומריבה) \u0003היו, והיו נודרין הנאה זה מזה\u0004 בתדירות, \u0003עמדו אבותיהם וכתבו חלקיהן\u0004 בנכסי ציבור \u0003לנשיא,\u0004 כדי שלא יכשלו באיסור.","\u0003המודר הנאה מחבירו ואין לו,\u0004 לחבר, \u0003מה יאכל —\u0004 \u0003נותנו\u0004 את המאכל \u0003לאחר לשום\u0004 (לשם) \u0003מתנה, והלה,\u0004 המודר, \u0003מותר בה.\u0004 מסופר: \u0003מעשה באחד, ב\u0004עיר \u0003בית חורון שהיה אביו נודר הימנו הנאה, והיה\u0004 הבן \u0003משיא את בנו, ו\u0004רצה שאביו יהיה בסעודת הנישואין. מה עשה, \u0003אמר לחברו: חצר וסעודה נתונים הינן לפניך, אלא כדי שיבא אבא ויאכל עמנו בסעודה.\u0004 שעל ידי כך רצה להפקיע את האיסור שעל ידי הנדר, שיוכל גם אביו להשתתף בסעודה.","\u0003אמר\u0004 המקבל: \u0003אם שלי הם —\u0004 \u0003הרי הם מוקדשין\u0004 כולם \u0003לשמים\u0004 (לבית המקדש). \u0003אמר לו\u0004 הנותן בכעס: וכי \u0003נתתי לך את שלי שתקדישם לשמים?! אמר לו: נתת לי את שלך אלא\u0004 כדי \u0003שתהא אתה ואביך אוכלין ושותין ומתרצין זה לזה\u0004 בתוך כך, \u0003ויהא עון\u0004 של הנדרים \u0003תלוי בראשו\u0004 של זה שהסכים וגרם לכך שיעברו על הנדר, כלומר, בראשי. בעקבות אותו מעשה \u0003אמרו חכמים\u0004 בענין זה: \u0003כל מתנה שאינה\u0004 עם הסכמה פנימית של הנותן עד כדי \u0003שאם הקדישה\u0004 המקבל \u0003תהא מקודשת —\u0004 \u0003אינה מתנה.\u0004","על המעשה המסופר במשנה תוהים: \u0003מעשה לסתור!\u0004 שהרי קודם דובר במשנה שיכול לתת לחבירו מתנה כדי להפקיע מאיסור הנדר, ומיד מביאים מעשה הבא לסתור את ההלכה הזו! ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך יש לשנותה]:\u0006 \u0003ואם הוכיח סופו על תחילתו\u0004 שלא נתן מתנה זו אלא בתנאי זה בלבד, ולא התכוון לתיתה בשלימות — \u0003אסור. ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בבית חורון באחד, דהוה\u0004 \u0005[שהיה]\u0006 \u0003סופו מוכיח על תחילתו.\u0004","\u0003אמר רבא: לא שנו אלא\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"והינן לפניך אלא כדי שיבא אבא\",\u0004 שפירש הנותן כוונתו במתנה זו. \u0003אבל\u0004 אם \u0003אמר ליה\u0004 \u0005[לו]\u0006 בלשון פחות מפורשת, שאין בה תנאי, כגון: \u0003\"שיהו לפניך, שיבא אבא\" —\u0004 בזה אין איסור, כי \u0003\"מדעתך\" הוא\u0004 ש\u0003אמר ליה\u0004 \u0005[לו],\u0006 כלומר, כוונת דבריו שאם תרצה יכול אתה להזמין את אבי.","\u0003לישנא אחרינא אמרין לה\u0004 \u0005[\u0006ב\u0005לשון אחרת אומרים אותה\u0006 שמועה\u0005],\u0006 \u0003אמר רבא: לא תימא טעמא\u0004 \u0005[אל תאמר\u0006 ש\u0005הטעם]\u0006 דווקא כש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"והינן לפניך\" הוא\u0004 ש\u0003אסור, אבל\u0004 אם \u0003אמר לו \"הן לפניך שיבא אבא ויאכל\" —\u0004 \u0003מותר,\u0004 אין הדבר כן. \u0003אלא אפילו אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"הן לפניך שיבא אבא ויאכל\" —\u0004 \u0003אסור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003סעודתו מוכחת עליו,\u0004 שלשם כך נתן לו אותה מתנה."],["מסופר: \u0003ההוא גברא דהוה ליה ברא דהוה שמיט כיפי דכיתנא\u0004 \u0005[אדם אחד שהיה לו בן שהיה שומט\u0006 וגונב \u0005אלומות של פשתן].\u0006 \u0003אסרינהו לנכסיה עליה\u0004 \u0005[אסר\u0006 האב \u0005את נכסיו עליו,\u0006 על הבן\u0005]\u0006 שלא יהנה מהם. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לאב: \u0003ואי הואי בר ברך צורבא מרבנן מאי\u0004 \u0005[ואם יהיה בן בנך\u0006 זה \u0005תלמיד חכם מה]\u0006 אתה עושה? \u0003אמר להון\u0004 \u0005[להם]\u0006 הנודר: \u0003ליקני הדין\u0004 \u0005[שיקנה, זה,\u0006 בני\u0005]\u0006 את הנכסים, \u0003ו\u0004באופן ש\u0003אי הואי בר ברי צורבא מרבנן, לקנייה\u0004 \u0005[אם יהיה הבן\u0006 של \u0005בני תלמיד חכם, שיקנה אותם]\u0006 לנכד. ושאלו: \u0003מאי\u0004 \u0005[מה]\u0006 הדין בכגון זה?","\u0003אמרי פומבדיתאי\u0004 \u0005[היו אומרים\u0006 חכמי \u0005פומבדיתא]:\u0006 אין זה קנין, כי \u0003\"קני\u0004 \u0005[קנה]\u0006 \u0003על מנת להקנות\" הוא,\u0004 שאינו מקנה למקבל דבר, אלא המקבל הוא רק כמעביר את הזכות לאדם אחר, וכן כאן, אין רצונו של האב להקנות לבנו שיהיה שלו, אלא רק על מנת שיקנה לנכד לכשיגדל, \u0003וכל \"קני על מנת להקנות\" —\u0004 \u0003לא קני\u0004 \u0005[אינו קונה],\u0006 ולא חל כאן קנין.","\u0003ורב נחמן אמר: קני\u0004 \u0005[קונה\u0006 הוא\u0005],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 מצינו בכגון זה שהדבר מועיל, שהרי גם קנין עושים ב\u0003סודרא\u0004 \u0005[סודר]\u0006 \u0003\"קני על מנת להקנות\" הוא,\u0004 שהרי כאשר נותן סודר למקנה על מנת לעשות בו את הקנין, אין המקנה לוקח לעצמו את הסודר, וכל קניינו בסודר הוא על מנת להקנות לאחר חפץ או נכס כלשהו, ובכל זאת חל הקנין.","\u0003אמר רב אשי: ומאן לימא לן\u0004 \u0005[ומי יאמר לנו]\u0006 \u0003דסודרא\u0004 \u0005[שהסודר]\u0006 שבו עושים קנין \u0003אי תפיס ליה לא מיתפיס\u0004 \u0005[אם תופס אותו\u0006 זה שהקנו לו את הסודר \u0005אינו נתפס\u0006 ונקנה לו\u0005]?\u0006 אלא שאין אנשים רגילים לעשות כן, אבל מבחינת הקנין — אין חסרון בקנין. \u0003ועוד\u0004 יש להבדיל בין הדברים: \u0003סודרא\u0004 \u0005[סודר]\u0006 שמקנים הוא אמנם \u0003\"קני\u0004 \u0005[קנה]\u0006 \u0003על מנת להקנות,\" ו\u0004אולם \u0003\"קני מן השתא\"\u0004 \u0005[קנה מעכשיו]\u0006 הוא, שקנין סודר בא על מנת להחיל את הקנין מאותו רגע. אולם \u0003הלין ניכסין דהדין\u0004 \u0005[אותם הנכסים של זה]\u0006 שנדר והקנה לבן בנו \u0003לאימתי קני\u0004 \u0005[מתי\u0006 הוא \u0005קונה]\u0006 — \u0003לכי הוי בר בריה\u0004 \u0003צורבא מרבנן\u0004 \u0005[לכאשר יהיה בן בנו תלמיד חכם],\u0006 אך \u0003לכי הוה\u0004 \u0005[כאשר יהיה]\u0006 תלמיד חכם — הלא כבר \u0003הדר סודרא למריה\u0004 \u0005[חזר הסודר לבעליו]\u0006 ונמצא שבשעה שהיה צריך הקנין לחול, עדיין לא חל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: והא\u0004 \u0005[והרי]\u0006 \u0003מתנת בית חורון\u0004 המוזכרת במשנתנו ש\u0003\"קני על מנת להקנות\" הוא, ולא קא קני\u0004 \u0005[ואינו קונה]\u0006 כלל!","ומספרים: \u0003זימנין\u0004 \u0005[לפעמים]\u0006 כששאל אותו שאלה זו \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משום\u0004 ש\u0003סעודתו מוכחת עליו,\u0004 כלומר, במתנת בית חורון לא היה חסרון בקנין עצמו, אלא שהתברר שבאמת לא התכוון להקנות לו דבר. \u0003וזימנין\u0004 \u0005[ופעמים]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן שהלכה זו של מתנת בית חורון כשיטת \u0003ר' אליעזר היא\u0004 ש\u0003אמר: אפילו ויתור\u0004 שכרגיל מוותרים אנשים זה לזה, ואין מקפידים על כך, \u0003אסור במודר הנאה.\u0004 וכמו כן הוא מחמיר במודר הנאה, שצריך קנין גמור, ולא די בקנין על מנת להקנות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003אמרו חכמים: כל מתנה שאינה\u0004 ניתנת על דעת \u0003שאם הקדישה\u0004 המקבל \u0003תהא מקודשת —\u0004 \u0003אינה מתנה.\u0004 ושואלים: \u0003\"כל\"\u0004 שאמר במשנה להוסיף ולהכליל דברים, \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]?\u0006 \u0003לאו לאתויי הא מילתא דשדיא בכיפי\u0004 \u0005[האם לא להביא\u0006 כגון \u0005דבר זה של שומט אלומות\u0006 הפשתן\u0005],\u0006 לומר שאם הקנה רק על מנת להקנות לאחר זמן אין זו מתנה? ודוחים: \u0003לא,\u0004 הכוונה היא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003לישנא בתראה דשמעתיה\u0004 \u0005[הלשון האחרונה של שמועתו]\u0006 של\u0003רבא\u0004 לענין מתנת בית חורון, שלא רק כשעושה תנאי מפורש שאינו נותן אלא על מנת שיבוא האב, אלא גם אם רק מסביר שזו כוונתו — אסור, שברור שלא היתה כאן הקניה אלא בתנאי זה, ואין זה קנין גמור.",""],["\u0003הנודר מן המבושל —\u0004 \u0003מותר בצלי ובשלוק\u0004 שאינם בכלל \"מבושל\". ואם \u0003אמר \"קונם תבשיל שאיני טועם\" —\u0004 \u0003אסור במעשה קדרה\u0004 (תבשיל) \u0003רך\u0004 (דליל), \u0003ומותר ב\u0004תבשיל \u0003עבה\u0004 (סמיך), שבשימוש הלשון של בני אדם אינו נכלל בגדר תבשיל. \u0003ו\u0004כן \u0003מותר בביצה טורמוטא ובדלעת הרמוצה,\u0004 שאף הן אינן נקראות בפי האנשים תבשילים. \u0003הנודר ממעשה קדרה —\u0004 \u0003אין אסור אלא ממעשה רתחתה\u0004 (תבשיל שעיקר עשייתו מרתיחת הקדירה), אבל אם \u0003אמר \"קונם היורד\u0004 (הנכנס) \u0003לקדרה שאיני טועם\" —\u0004 \u0003אסור בכל\u0004 הדברים \u0003המתבשלין בקדרה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יאשיה\u0004 אומר שהנודר מן המבושל \u0003אוסר\u0004 בכך את עצמו גם בצלי, \u0003ואף על פי שאין\u0004 בכתוב \u0003ראיה לדבר\u0004 — מכל מקום יש בו \u0003זכר\u0004 (רמז) \u0003לדבר, שנאמר: \"ויבשלו (את) הפסח באש כמשפט\"\u0004 (דברי הימים ב לה, יג), וכיון שפסח אינו נאכל אלא צלי, משמע שגם צלייה קרויה בישול.","ושואלים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר שב\u0006עקרון \u0005זה\u0006 הם \u0005חולקים];\u0006 ש\u0003ר' יאשיה סבר:\u0004 בנדרים \u0003הלך אחר לשון תורה,\u0004 ובלשון תורה צלי הוא בכלל מבושל, \u0003ותנא דילן\u0004 \u0005[והתנא שלנו]\u0006 \u0003סבר: בנדרים הלך אחר לשון בני אדם?\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003בנדרים הלך אחר לשון בני אדם,\u0004 אלא \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה\u0006 אמר את דבריו \u0005כ\u0006לשון של \u0005מקומו וחכם זה כ\u0006ב\u0005מקומו];\u0006 \u0003באתרא דתנא דילן\u0004 \u0005[במקומו של התנא שלנו]\u0006 \u0003לצלי קרו ליה\u0004 \u0005[קוראים אותו]\u0006 \u0003צלי,\u0004 \u0003ולמבושל קרו ליה\u0004 \u0005[קוראים אותו]\u0006 \u0003מבושל. באתרא\u0004 \u0005[במקומו]\u0006 של \u0003ר' יאשיה אפילו\u0004 ל\u0003צלי קרו\u0004 \u0005[קוראים]\u0006 \u0003מבושל.\u0004","ומקשים: \u0003והא קרא נסיב לה\u0004 \u0005[והרי מקרא\u0006 הוא \u0005מביא]\u0006 ועליו הוא סומך ואם כן אין לדעתו לחלק בין מקום למקום! ומשיבים: דבריו אלה הם \u0003אסמכתא בעלמא\u0004 \u0005[\u0006כ\u0005סמך\u0006 ורמז \u0005בלבד]\u0006 וכך נראה מלשונו, שהרי הוא אומר שיש בכך רק זכר לדבר.","שנינו במשנה: האומר \u0003\"קונם תבשיל\u0004 שאיני טועם\" — מותר במעשה קדירה עבה. ושואלים: מדוע מותר? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מתבשיל נדר\u0004 וזה כולל הכל!","\u0003אמר אביי: האי תנא\u0004 \u0005[תנא זה]\u0006 סבור ש\u0003כל מידי\u0004 \u0005[דבר]\u0006 \u0003דמתאכל ביה ריפתא\u0004 \u0005[שנאכל בו,\u0006 עימו, \u0005לחם]\u0006 — \u0003תבשיל קרו ליה\u0004 \u0005[קוראים אותו],\u0006 ומעשה קדירה עבה נאכל בלי לחם. \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנודר מן התבשיל —\u0004 \u0003אסור בכל מיני תבשיל, ואסור בצלי ובשלוק ובמבושל, ואסור בהיטריות\u0004 (דלעות) \u0003רכות שהחולין אוכלין בהן פיתן.\u0004 משמע מכאן שדבר הנאכל עם לחם נקרא תבשיל.","ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כך הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' ירמיה חלש\u0004 \u0005[חלה],\u0006 \u0003על לגביה ההוא אסיא לאסיוה\u0004 \u0005[נכנס אליו רופא אחד לרפאותו],\u0006 \u0003חזא קרא דמחת בביתיה\u0004 \u0005[ראה דלעת שמונחת בביתו],\u0006 \u0003שבקיה ונפק\u0004 \u0005[הניחו ויצא].\u0006 \u0003אמר: מלאך מותא אית ליה לדין בביתיה ואנא איעול לאסאה יתיה\u0004 \u0005[מלאך המוות\u0006 (הדלעת) \u0005נמצא לו לזה בביתו ואני אכנס לרפא אותו]?!\u0006 הרי שדלעת מזיקה לחולה!","ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהם טובים לחולי — \u0003ברכיכי\u0004 \u0005[ב\u0006דלועים \u0005רכים],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהם רעים לגוף — \u0003באשוני\u0004 \u0005[בקשים].\u0006 \u0003רבא בר עולא אמר:\u0004 יש לומר, \u0003הא\u0004 \u0005[זה]\u0006 שהיא קשה לגוף — \u0003בקרא גופיה\u0004 \u0005[בדלעת עצמה],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 שהיא טובה לחולי — \u0003בגוויה דקרא\u0004 \u0005[בתוכה של הדלעת].\u0006 ש\u0003אמר רב יהודה: לוליבא דקרא\u0004 \u0005[תוכו של הדלעת]\u0006 יפה לאכול אותו \u0003בסילקא\u0004 \u0005[עם תרד],\u0006 \u0003לוליבא דכיתנא בכותחא\u0004 \u0005[תוכם של\u0006 זרעוני ה\u0005פשתן\u0006 טוב לאכול אותו \u0005בכותח].\u0006 \u0003ודבר זה אסור לאומרו בפני עם הארץ,\u0004 כדי שלא יעקרו את הפשתן לצורכי אכילה.","\u0003רבא אמר: מאן\u0004 \u0005[מי]\u0006 הם ה\u0003חולין\u0004 המוזכרים כאן שמועילה להם הדלעת — \u0003רבנן\u0004 \u0005[חכמים],\u0006 שמפני שהם עוסקים בתורה ועמלים בה הם נחלשים, אבל הם אינם חולים ממש, ולכן יכולים לאכול דלעת זו, אבל לחולים ממש הדבר מזיק. ומעירים, כי \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר רבא:\u0004"],["\u0003כמאן מצלינן על קצירי ועל מריעי\u0004 \u0005[כ\u0006דעת \u0005מי אנו מתפללים\u0006 בכל יום \u0005על החולים ועל הסובלים]\u0006 \u0003[כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 — \u0003כ\u0004דעת \u0003ר' יוסי]\u0004, שאומר שאדם נידון בכל יום, ולא רק בראש השנה, ולכן יש טעם להתפלל עליו. \u0003מדאמר קצירי ומריעי\u0004 \u0005[מ\u0006תוך \u0005שאמר חולים וסובלים]\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 : \u0003קצירי\u0004 כוונתו \u0003קצירי\u0004 \u0005[חולים]\u0006 \u0003ממש, מריעי\u0004 \u0005[סובלים]\u0006 הם \u0003רבנן\u0004 \u0005[חכמים]\u0006, כי בדרך כלל חכמים חלושים הם בגופם.","שנינו במשנה כי הנודר מן התבשיל \u0003מותר ב\u0004תבשיל \u0003עבה.\u0004 ומעירים: \u0003מתניתין דלא כבבלאי\u0004 \u0005[משנתנו אינה כ\u0006מנהג ה\u0005בבלים]\u0006 ש\u0003אמר ר' זירא: בבלאי טפשאי\u0004 \u0005[בבליים טפשים\u0006 הם\u0005]\u0006, \u0003דאכלי לחמא בלחמא\u0004 \u0005[שאוכלים לחם בלחם],\u0006 שאוכלים תבשיל עבה של דייסה בלחם, ונמצא כאילו אוכלים סוג אחד של לחם בלחם אחר. ולמנהגם, אף תבשיל עבה אסור על הנודר מן התבשיל.","ובאותו ענין \u0003אמר רב חסדא: דמשאיל להון להלין נקדני\u0004 \u0005[ששאלו אותם את המפונקים הללו]\u0006 של העיר \u0003הוצל\u0004 שבבבל: \u0003הדין דייסא, היכין מעלי למיכלה\u0004 \u0005[דייסה זו, איך טוב יותר לאכול אותה]\u0006? \u0003דחיטי\u0004 \u0005[\u0006דייסה \u0005של חיטים]\u0006 — \u0003בלחמא דחיטי\u0004 \u0005[בלחם חיטים],\u0006 \u0003ודשערי\u0004 — \u0003בלחמא דשערי\u0004 \u0005[בלחם שעורים],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003דחיטי\u0004 \u0005[\u0006דייסה \u0005של חיטים]\u0006 — \u0003בדשערי\u0004 \u0005[ב\u0006לחם \u0005שעורים]\u0006 \u0003ודשערי\u0004 \u0005[ו\u0006דייסה \u0005של שעורים]\u0006 — \u0003בדחיטי\u0004 \u0005[ב\u0006לחם \u0005חיטים]\u0006?","ומספרים: \u0003רבא אכליה\u0004 \u0005[היה אוכלו]\u0006 עם \u0003חסיסי\u0004 שהוא דייסה של קליות שעורים. ועוד מסופר: \u0003רבה בר רב הונא אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003לרב הונא דקאכיל דייסא באצבעתיה\u0004 \u0005[שהוא\u0006 \u0005אוכל דייסה באצבעותיו]\u0006. \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003אמאי קאכיל מר בידיה\u0004 \u0005[מדוע אוכל אדוני בידו]\u0006? \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: דייסא באצבעתא בסים\u0004 \u0005[דייסה\u0006 הנאכלת \u0005באצבע טעימה\u0006 יותר\u0005]\u0006, \u0003וכל\u0004 ש\u0003כן\u0004 אם נאכלת \u0003בתרתין\u0004 \u0005[בשתיים,\u0006 אצבעות\u0005]\u0006 \u0003וכל\u0004 ש\u0003כן בתלת\u0004 \u0005[בשלוש]\u0006, שנעים יותר לאכול אותה בידיים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לחייא בריה\u0004 \u0005[בנו]\u0006, \u0003וכן אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרבה בריה\u0004 \u0005[בנו]\u0006 : אם \u0003מזמנים לך למיכל דייסא\u0004 \u0005[מזמינים אותך לאכול דייסה]\u0006 לך לסעודה כזו \u0003עד\u0004 מרחק של \u0003פרסה.\u0004 אם מזמינים אותך \u0003למיכל בישרא דתורא\u0004 \u0005[לאכול בשר שור]\u0006 לך אפילו \u0003עד תלתא פרסין\u0004 \u0005[שלוש פרסות]\u0006. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לחייא בריה\u0004 \u0005[בנו]\u0006, \u0003וכן אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרבה בריה\u0004 \u0005[בנו]\u0006 : \u0003כל מידעם\u0004 \u0005[דבר]\u0006 \u0003לא תפלוט קמיה\u0004 \u0005[לפני]\u0006 \u0003רבך,\u0004 שיש בכך משום ביזיון לרב, \u0003לבר מן קרא ודייסא\u0004 \u0005[חוץ מדלעת ודייסה]\u0006 \u0003ש\u0004כאשר אינם מתעכלים \u0003הן דומין לפתילתא של אבר\u0004 \u0005[פתילת עופרת]\u0006 רותחת במעיים, \u0003ואפילו קמי\u0004 \u0005[לפני]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003פלוט\u0004 אותן, משום שיש סכנה בדבר.","מסופר: \u0003ר' יוסי ור' יהודה\u0004 אכלו יחד; \u0003חד אכיל דייסא באצבעתיה\u0004 \u0005[אחד\u0006 מהם \u0005היה אוכל דייסה באצבעותיו]\u0006 \u0003וחד אכיל בהוצא\u0004 \u0005[ואחד היה אוכל במקל,\u0006 כעין מזלג\u0005]\u0006. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003דאכיל בהוצא לדאכיל באצבעתיה\u0004 \u0005[\u0006זה \u0005שהיה אוכל במקל ל\u0006זה \u0005שהיה אוכל באצבעותיו]\u0006 : \u0003עד מתי אתה מאכילני צואתך,\u0004 את לכלוך הציפורניים שלך! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003דאכיל באצבעתיה לדאכיל בהוצא\u0004 \u0005[\u0006זה \u0005שהיה אוכל באצבעותיו ל\u0006זה \u0005שהיה אוכל במקל]\u0006 : \u0003עד מתי אתה מאכילני רוקך\u0004 שאתה מכניס את המקל לפיך ואחר כך אתה מכניס אותו שוב לקערה המשותפת!","מסופר: \u0003ר' יהודה ור' שמעון אייתו לקמייהו בלוספיין\u0004 \u0005[הביאו לפניהם מין תאנים].\u0006 \u0003ר' יהודה אכל, ר' שמעון לא אכל. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה: מאי טעמא לא אכיל מר\u0004 \u0005[מה טעם אין אדוני אוכל]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון: אלו אין יוצאין מבני מעים כל עיקר,\u0004 כלומר, אינם מתעכלים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה:\u0004 אם כך הם ממלאים את המעיים \u0003כל שכן שנסמוך עליהן למחר,\u0004 שראוי לנו לאכול מהם, כדי שנרגיש שבעים גם למחר.","מסופר: \u0003ר' יהודה הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003ר' טרפון. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' טרפון: היום פניך צהובין\u0004 (אדומים וטובים). \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמש יצאו עבדיך\u0004 כלומר, אנו, התלמידים, \u0003לשדה, והביאו לנו תרדין, ואכלנום בלא מלח\u0004 ומשום כך פנינו צהובים, \u0003ואם אכלנום במלח —\u0004 \u0003כל שכן שהיו פנינו צהובין.\u0004","אגב כך מספרים: \u0003אמרה ההיא מטרוניתא\u0004 \u0005[גבירה\u0006 גויה \u0005אחת]\u0006 \u0003לר' יהודה:\u0004 כיצד ייתכן שיהא אדם \u0003מורה\u0004 הוראות לישראל \u0003ורוי\u0004 \u0005[ו\u0006גם \u0005שיכור]?\u0006 שהיו פניו אדומים ויפים. \u0003אמר לה: הימנותא בידא דההיא איתתא\u0004 \u0005[נאמנות,\u0006 באמונה, \u0005בידי אשה זו]\u0006 \u0003אי טעימנא אלא קידושא ואבדלתא וארבעה כסי דפסחא\u0004 \u0005[אם אני טועם\u0006 יין \u0005אלא של קידוש והבדלה וארבע כוסות של פסח],\u0006 \u0003ו\u0004גם אחרי ארבע כוסות אלה \u0003חוגרני\u0004 (קושר אני) את \u0003צידעי\u0004 (רקותי) \u0003מן הפסח עד העצרת,\u0004 מפני שהיין קשה לי וגורם לי לכאב הראש. \u0003אלא\u0004 מדוע פניו אדומים וטובים — כאמור: \u0003\"חכמת אדם תאיר פניו\"\u0004 (קהלת ח, א).","מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לר' יהודה\u0004 שהיו פניו טובים: \u0003פניך דומין אי\u0004 \u0005[או]\u0006 \u0003כמלוי רבית אי\u0004 \u0005[או]\u0006 \u0003כמגדלי חזירין,\u0004 שהם אנשים שמרוויחים הרבה ויגעים מעט, ולכן פניהם שמנות וטובות. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ביהודאי תרוייהו אסירן\u0004 \u0005[אצל יהודים שניהם אסורים].\u0006 \u0003אלא\u0004 מדוע פני טובים כל כך — \u0003עשרים וארבעה בית הכסא אית\u0004 \u0005[יש]\u0006 \u0003לי\u0004 בדרך \u0003מן ביתא עד בי מדרשא\u0004 \u0005[מן הבית עד בית המדרש]\u0006 \u0003וכל שעה ושעה אני נכנס לכל אחד ואחד.\u0004 ומכיון שאיננו סובל מעצירות דבר זה גורם לו שיהיו פניו טובים.","מסופר: \u0003ר' יהודה כד אזיל לבי מדרשא\u0004 \u0005[כאשר היה הולך לבית המדרש]\u0006 \u0003שקיל גולפא על כתפיה\u0004 \u0005[היה נוטל קנקן על כתפו]\u0006 כדי שיוכל אחר כך לשבת עליו, \u0003אמר: גדולה מלאכה שמכבדת את בעליה,\u0004 שבגלל מלאכה זו יוכל אחר כך לשבת בכבוד בבית המדרש. כעין זה מסופר ש\u0003ר' שמעון שקיל צנא על כתפיה\u0004 \u0005[נוטל סל על כתפו],\u0006 \u0003אמר: גדולה מלאכה שמכבדת את בעליה.\u0004","מסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' יהודה נפקת\u0004 \u0005[יצאה\u0006 לשוק\u0005],\u0006 \u0003נקטת עמרא\u0004 \u0005[ליקטה צמר],\u0006 \u0003עבדה גלימא דהוטבי\u0004 \u0005[\u0006ו\u0005עשתה\u0006 ממנו \u0005גלימה עבה].\u0006 \u0003כד נפקת לשוקא מיכסיא ביה\u0004 \u0005[כאשר היתה יוצאת לשוק היתה מתכסה בה],\u0006 \u0003וכד נפיק\u0004 \u0005[וכאשר היה יוצא]\u0006 \u0003ר' יהודה לצלויי הוה מכסי ומצלי\u0004 \u0005[להתפלל, היה מתכסה\u0006 בגלימה זו \u0005ומתפלל].\u0006 \u0003וכד מיכסי ביה\u0004 \u0005[וכאשר\u0006 היה \u0005מתכסה בו]\u0006 \u0003הוה\u0004 \u0005[היה]\u0006 \u0003מברך \"ברוך שעטני מעיל\"\u0004 שכל כך נהנה מכך.","מסופר: \u0003זימנא חדא\u0004 \u0005[פעם אחת]\u0006 \u0003גזר רבן שמעון בן גמליאל\u0004 הנשיא \u0003תעניתא\u0004 \u0005[תענית],\u0006 \u0003ר' יהודה לא אתא\u0004 \u0005[בא]\u0006 \u0003לבי תעניתא\u0004 \u0005[לבית התענית],\u0006 למקום שבו נאספו הכל. \u0003אמרין ליה\u0004 \u0005[אמרו לו]\u0006 לרבן שמעון בן גמליאל: \u0003לא אית ליה כסויא\u0004 \u0005[אין לו כיסוי],\u0006 שאין לו בגד מכובד להתכסות בו ולכן איננו בא לאסיפת הרבים. \u0003שדר ליה\u0004 \u0005[שלח לו]\u0006 רבן שמעון בן גמליאל \u0003גלימא\u0004 \u0005[גלימה]\u0006 משלו שיוכל להתכסות, \u0003ולא קביל\u0004 \u0005[קיבל],\u0006 לא הסכים ר' יהודה לקבל מתנה זו."]]};
